programs.sol:
"""Finnish/Estonian vocabulary and spelling, strengthened by nearby Finnish text.

Country/language/city names have a direct response. For other tokens, a fading
context detector amplifies Finnish inflections, doubled letters and front vowels.
The .fi domain is a cue only when the preceding text looks Finnish.
It sees completed words, not arbitrary tokenizer fragments as function words.
Training showed the largest coherent responses on these words and spellings;
unrelated small lexical responses are deliberately left unmodeled.
"""
from functools import lru_cache
import re

READS = ()
FINLAND = {'finland','suomi','suomen','finlande','finnland','finlandia'}
FINNISH = {'finnish','suomalainen','suomalaiset','suomalais','suomal'}
ESTONIA = {'estonia','estonian','eesti','eestis','estland','estonie','eston'}
CITIES = {
    'helsinki', 'helsing', 'elsinki', 'tallinn',
    'tampere', 'turku', 'espoo', 'vantaa',
}
BALTIC = {'lithuania','lithuanian','latvia','latvian','lietuva','latvija'}
CASES = ('ssa','ssä','sta','stä','lla','llä','lta','ltä','lle','ksi','tta','ttä')
NOMINAL = ('inen','ainen','äinen','minen','isuus','nen','iset','isen','isten')
PARTICIPLES = ('nut','nyt','neet','anut','ynyt','ettu','tty')
DERIVATION = ('kse','ksen','mis','mist','uden','uuden','yys','uus','isu')
VOWELS = set('aeiouyäöõ')


FINNISH_WORDS = set('''ja ei oli ovat että mutta myös sekä tai kuin voi joka jotka
    tämä hän sen kun niin vielä hyvin kaikki vain nyt sitten olla ole onko yksi
    kaksi tässä siitä mitä miten jos koska kanssa jälkeen ennen paljon hänellä
    jotka joten ollut tulee tulla aina jotta ilman meidän heidän minun sinun
    täällä siellä tuolla tänne tänään missä miksi hyvin enemmän
    myös mikä nämä nekin'''.split())
OTHER_WORDS = set('''the and of to in is was for with that this und der die das ein
    eine ist mit och att det är som en för av till med har den jag nicht auch
    sich werden nicht auf wir sie er bei im nicht om vi du de så men ett
    por para não uma que com em da do uma você eu ele ela les des une le la
    je et pas mais ou nous vous leur'''.split())
NATIVE = set('aeiouyäöõdhjklmnprstv')
VOWEL_PAIRS = ('aa','ee','ii','oo','uu','yy','ää','öö','yö','äy','öy')
STRONG_ENDINGS = CASES + ('inen',)
PIECES = re.compile(r'[^\W\d_]+|[\W\d_]+')


def word_evidence(word, evidence):
    w = word.lower()
    if w in OTHER_WORDS:
        return -1.5
    if w in FINNISH_WORDS:
        return 1.2
    if evidence > .25 and len(w) >= 5 and set(w) <= NATIVE:
        if w.endswith(STRONG_ENDINGS):
            return 1.0
        if any(pair in w for pair in VOWEL_PAIRS):
            return .4
    if any(c in w for c in 'åüßéèêáàãâóòôõçčšžőű'):
        # õ is an Estonian cue, unlike the other accents in this set.
        return .8 if 'õ' in w else -.8
    return 0.0


def context(carry, s, doc):
    if carry is None or carry[0] != doc:
        word, evidence = '', 0.0
    else:
        _, word, evidence = carry
    evidence *= .96
    for piece in PIECES.findall(s):
        if piece[0].isalpha():
            old = word
            word = (word + piece.lower())[-60:]
            if 'ä' in word and 'ä' not in old:
                evidence += .3
            if 'õ' in word and 'õ' not in old:
                evidence += .7
            if any(pair in word and pair not in old for pair in ('ää','öö','yö')):
                evidence += .8
        else:
            if word:
                evidence += word_evidence(word, evidence)
                word = ''
    evidence = max(0.0, min(7.0, evidence))
    language = min(1.0, max(0.0, (evidence - .75) / 3.0))
    return (doc, word, evidence), language


@lru_cache(maxsize=30000)
def lexical_response(s):
    """Return the direct response and the extra response in Finnish context."""
    w = s.strip().lower()
    native = bool(w) and w.isalpha() and set(w) <= NATIVE
    lower = native and s.strip().islower()
    space = s.startswith(' ')
    front_pair = 'ää' in w or 'öö' in w

    # Semantic cues work even in otherwise English text.
    if w in FINLAND:
        base = 3.6
    elif w in FINNISH:
        base = 3.9
    elif w in ESTONIA:
        base = 3.8
    elif w in CITIES:
        base = 2.0
    elif w in BALTIC:
        base = .6
    elif w == '.fi':
        return 0.0, 4.7
    else:
        base = 0.0

    # A few distinctive letters and inflections give small direct cues.
    if w == 'ä':
        base += .27
    elif w == 'ö':
        base -= .04
    elif w == 'õ':
        base += .56
    if front_pair:
        base += 3.5
    if native and len(w) >= 4 and w.endswith(NOMINAL):
        base += .07
    if native and len(w) >= 3 and w.endswith(CASES):
        base += .09
    if space and w in FINNISH_WORDS:
        base += .41
    if w.isdigit():
        base -= .003

    if not native:
        return base, 0.0
    if not lower:
        return base, .32

    # Spelling of lowercase word pieces: vowels, inflections and clusters.
    spelling = -.03 if space else 1.03
    spelling += .71 * min(3, sum(c in VOWELS for c in w))
    spelling += .34 if len(w) == 1 else .30 if len(w) == 2 else .20
    if w.endswith(CASES):
        spelling += .59
    if w.endswith(NOMINAL):
        spelling += 2.61
    if w.endswith(PARTICIPLES):
        spelling += 2.10
    if w.endswith(('sti', 'asti', 'esti')):
        spelling += 1.50
    if w.endswith(DERIVATION):
        spelling += 2.90
    if any(pair in w for pair in ('tt', 'kk', 'pp', 'ss', 'nn', 'll')):
        spelling += .40
    if any(pair in w for pair in ('ht', 'hd', 'ks', 'nk')):
        spelling += 1.17
    spelling += 1.80 * ('ä' in w) + .96 * ('ö' in w) + 1.78 * ('õ' in w)
    if w in FINNISH_WORDS:
        spelling += 1.75
    if front_pair:
        # These already have a strong direct response, even without context.
        spelling -= 3.86
    return base, spelling


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    carry, language = context(carry, s, prefix.document_ids[-1])
    base, spelling = lexical_response(s)
    return carry, float(base + language * spelling)

