"""A weak negative signal for words about knowing, wanting, or needing."""
READS = ()

MENTAL_STATE = {
    "know", "understand", "appreciate", "assume", "obvious", "sure",
    "mean", "think", "believe",
}
NEED_OR_HOPE = {"need", "must", "want", "hope", "hoping", "depend"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in MENTAL_STATE or word in NEED_OR_HOPE:
        return None, -0.12
    return None, 0.0

programs.sol:
"""A negative lexical signal for enemies and other adversarial associations.

Enemy/foe vocabulary is strongest, followed by opponents, evil agents,
hazards, insults, and warfare. Some forms are Chinese/Japanese
words.  These are word associations, not judgments about real people.
Short memory recognizes split words and 'World War'. Other text is zero.
"""
import re

READS = ()

OPPONENTS = set('opponent opponents adversary adversaries hostile'.split())
EVIL_AGENTS = set('evil villain villains devil demons demonic sinister '
                  'attacker attackers culprit perpetrator'.split())
HAZARDS = set('danger dangers threat threats harmful malign malignant '
              'malicious pathogens parasite monster monsters vile'.split())
CONFLICT = set('warfare battlefield weapons weapon arsenal army defense '
               'defenses terrorist terrorists rebel nazi'.split())
OUTSIDERS = set('foreign foreigners stranger strangers'.split())
MILD_HOSTILITY = set('wicked aggressive aggression hatred hateful insulting '
                    'rival rivals antagonist murderer criminals opposing'.split())

# A threatening description, an adversarial organization, and a French insult.
STRONG_ASSOCIATIONS = {
    'formidable': -0.66, 'taliban': -0.91, 'salope': -0.86,
}

# Translations: enemy; bandit/thief; opponent; ghost/demon/evil; harm/conflict.
CHINESE = {
    '敌': -3.55, '敵': -2.90, '敌人': -2.86,
    '匪': -1.37, '贼': -1.30, '寇': -1.63, '魔鬼': -1.35,
    '对手': -0.92, '对方': -0.76, '對方': -0.68, '竞争对手': -0.50,
    '鬼': -0.89, '魔': -0.73, '邪': -0.87, '邪恶': -0.95,
    '恶魔': -0.85, '惡': -0.69, '仇': -0.58, '怪物': -0.74,
    '妖': -0.47, '妖怪': -0.62, '僵尸': -0.56,
    '侵略': -0.72, '入侵': -0.35, '战争': -0.47, '战斗': -0.43,
    '病毒': -0.47, '毒': -0.31, '阴谋': -0.54,
}
SPLIT_ENDINGS = {
    ('enemies', 'emies'): -0.98, ('opponent', 'onent'): -0.71,
    ('opponents', 'onents'): -0.60, ('pathogen', 'ogen'): -0.77,
    ('assailant', 'ant'): -0.55, ('assailants', 'ants'): -0.41,
    ('aggressor', 'or'): -0.57,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    text = prefix.token_strings[-1]
    word = text.strip()
    lower = word.lower()
    value = STRONG_ASSOCIATIONS.get(lower, CHINESE.get(word, 0.0))
    if lower == 'enemy':
        value = -2.20
    elif lower == 'enemies':
        value = -1.52
    elif lower in {'foe', 'foes'}:
        value = -1.27
    elif lower in OPPONENTS:
        value = -0.80
    elif lower in EVIL_AGENTS:
        value = -0.63
    elif lower in HAZARDS:
        value = -0.38
    elif lower in CONFLICT:
        value = -0.28
    elif lower in OUTSIDERS:
        value = -0.35
    elif lower in MILD_HOSTILITY:
        value = -0.20
    elif lower in {'combat', 'aggress', 'hostility'}:
        value = -0.50
    elif lower == 'assail':
        value = -1.12
    elif lower == 'war':
        value = -0.10
    if word == 'War':
        value = -0.62 if previous == 'world' else -0.30
        if not text.startswith(' '):
            value = -0.10
    elif word == 'WAR':
        value = -0.05
    if word == 'Combat':
        value = -0.32
    if lower == 'evil' and (word != 'evil' or not text.startswith(' ')):
        value = -0.41
    if word == 'Enemy' and not text.startswith(' '):
        value = -1.65

    if word == '人' and previous in {'敌', '敵'}:
        value = -1.35  # The second character of 'enemy/person opposed to us'.

    match = re.search(r'[^\W\d_]+$', tail + text.lower())
    tail = match.group(0)[-24:] if match else ''
    if not text[:1].isspace():
        value = SPLIT_ENDINGS.get((tail, lower), value)
    return (doc, lower, tail), float(value)

"""A lexical 'this kind' response, with smaller quotation-boundary responses.

Chinese demonstrative-plus-kind expressions dominate the positive tail. Japanese
'こういう' and 'そういう' have similar responses. Fused following nouns weaken
the Chinese response. Closing curly quotes usually have a negative response,
unless the token also contains a line break. English alternative adverbs and
'again' have smaller positive responses. Control tags have fixed offsets.
Unmodeled tokens are near zero; this does not reconstruct their lexical variation.
"""
READS = ()
TRADITIONAL = str.maketrans('這種類樣個', '这种类样个')
JAPANESE_KIND = {
    'こういう': 0.45,   # this kind of
    'そういう': 0.28,   # that kind of
    'どんな': 0.32,     # what kind of
    'こんな': 0.08,     # like this
    'そんな': -0.11,    # like that
}

ALTERNATIVE_ADVERBS = {
    'instead': 0.14,
    'alternatively': 0.06,
    'rather': 0.055,
    'otherwise': 0.03,
}

BOUNDARY_TAGS = {
    '<think>': -0.155,
    '</think>': 0.087,
    '<|endoftext|>': -0.02,
    '<|im_start|>': 0.006,
    '<|im_end|>': 0.017,
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    chinese = token.translate(TRADITIONAL)
    value = -0.001
    if chinese.startswith('在'):
        chinese = chinese[1:]
        leading_in = True
    else:
        leading_in = False
    if chinese.startswith(('这种', '这类')):
        if chinese.startswith('这类'):
            peak = 0.50
        else:
            peak = 0.54 if '這' in token else 0.61
        if leading_in:
            peak *= 0.9
        value = peak * 2 / max(2, len(chinese))
    elif chinese in ('这样', '这样的', '那种', '那类'):
        value = 0.13
    elif chinese in ('此种', '此类', '这两种'):
        value = 0.27
    elif (
        chinese.startswith('这')
        and chinese[1:] in ('款', '位', '座', '项', '份', '场')
    ):
        value = 0.14
    elif token in JAPANESE_KIND:
        value = JAPANESE_KIND[token]
    elif token.lower() in ALTERNATIVE_ADVERBS:
        value = ALTERNATIVE_ADVERBS[token.lower()]
    elif token.lower() == 'again':
        value = 0.095
    elif token in BOUNDARY_TAGS:
        value = BOUNDARY_TAGS[token]
    elif token == '】':
        value = -0.17
    elif token == '』':
        value = -0.13
    elif token == '」':
        value = -0.055
    elif token and token[-1] in '’”' and all(
        not c.isalnum() for c in token
    ):
        if '\n' in raw:
            value = 0.035
        elif token == '’':
            value = -0.16
        elif token[0] in '?？!！。…':
            value = -0.17
        elif token == '”':
            value = -0.09
        else:
            value = -0.06
    return None, float(value)

programs.luna:
"""Approximate this rare component with a Chinese demonstrative detector.

It assigns the typical positive activation to tokens meaning “this kind/type”
in simplified or traditional Chinese; other tokens predict zero. The harvest
shows this recurring lexical cue, but the rule omits the component's small
background variation and any context-dependent distinctions.
"""

READS = ()

SIMPLIFIED = {"这种", "这类"}
TRADITIONAL = {"這種"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "在这种":
        return None, 0.55
    if token in SIMPLIFIED:
        return None, 0.62
    if token in TRADITIONAL:
        return None, 0.54
    return None, 0.0

"""A sparse cue for words about order, recurrence, and distributing things."""

READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    """Mark explicit sequence and repetition words; otherwise predict no signal."""
    word = prefix.token_strings[-1].lower().strip(
        " \t\r\n.,;:!?()[]{}<>\"'`*_-/"
    )

    # Repeated or distributed actions.
    if word == "each":
        return None, -1.30
    if word == "every":
        return None, -1.00
    if word in {"once", "times"}:
        return None, -0.58

    # References to order: what came before, after, or at an endpoint.
    if word == "next":
        return None, -1.40
    if word == "previous":
        return None, -0.90
    if word == "last":
        return None, -1.05
    if word == "first":
        return None, -0.40
    if word == "second":
        return None, -0.63

    # A few corresponding sequence/iteration words seen in other scripts.
    if word == "次":
        return None, -6.60
    if word == "々":
        return None, -0.48
    if word == "初めて":
        return None, -1.15
    if word == "번호":
        return None, -0.53
    if word == "的机会":
        return None, -0.63
    if word == "轮":
        return None, -0.57
    if word == "长时间":
        return None, -0.66

    return None, 0.0

programs.sol:
"""Recognize colon delimiters by their typography and preceding label.

Ordinary colons fire strongly; digits and question/answer headings weaken
that response. Diagnostic labels strengthen it. Spaced, line-ending and
fullwidth colons are weaker, while URL, scope and assignment syntax are
mostly excluded. Initial title/question headings have separate responses.
"""
READS = ()
DIAGNOSTIC_LABELS = {'note', 'error', 'warning', 'debug'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
        position += 1
    value = 0.0
    if s == ':':
        word = previous.strip()
        value = 0.82 if word.isdigit() else 0.92 if len(word) == 1 else 1.10
        if word.lower() in DIAGNOSTIC_LABELS or word.endswith('Warning'):
            value = 1.44
        elif previous in {'Q', 'A'}:
            value = 0.40
        elif word == 'Answer':
            value = 0.56 if previous.startswith(' ') else 0.0
        elif word == 'Question':
            value = 0.40 if previous.startswith(' ') else -1.10
        elif previous == 'Title':
            value = -3.19 if position == 1 else 0.64
    elif s.lstrip().startswith(('::', ':=')):
        pass
    elif s.startswith('://'):
        value = 0.24
    elif s.startswith(':'):
        if '\n' in s:
            value = 0.66 if s.count('\n') == 1 else 0.54
        elif s.startswith(':\\'):
            value = 0.99
        elif s.startswith(':*'):
            value = 0.63
        else:
            value = 1.42 if s[1:].isalpha() else 1.25
    elif s.startswith(' :'):
        value = 0.19 if '\n' in s else 0.47
    elif s.startswith('：'):
        value = 0.36 if '\n' in s else 0.75
    elif s in {'":', "':"}:
        value = -0.05
    if position == 0 and s in {'Title', 'Question'}:
        value = 5.64 if s == 'Title' else 2.08
    return (doc, position, s), value

"""Approximate the large negative spikes on Greek word continuations.

A Greek token without leading whitespace gets a strong negative value when
it follows a whitespace-prefixed Greek token. The current letter and fragment
length set the strength. A preceding undecodable token gives a weaker version.
Other Greek tokens get small letter-based adjustments; non-Greek tokens get
zero. Only the preceding token is remembered, within the same document.
This captures the distinctive Greek spikes, not most background variation.
"""
import unicodedata
from functools import cache

READS = ()


@cache
def greek(s):
    return bool(s) and all(c.isalpha() and 'GREEK' in
                           unicodedata.name(c, '') for c in s)


def continuation(s):
    if len(s) != 1:
        return -0.10
    if s in 'ρτ':
        return -0.57
    if s in 'λπκχξμ':
        return -0.47
    if s in 'αεηί':
        return -0.42
    if s in 'ιυν':
        return -0.35
    if s == 'ο':
        return -0.36
    if s in 'άέύ':
        return -0.28
    if s in 'όω':
        return -0.17
    if '\u1f00' <= s <= '\u1fff':
        return -0.07
    return -0.25


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    s = token.strip()
    value = 0.0
    if greek(s):
        if token != token.lstrip():
            value = -0.03 if s in 'τνεδ' else 0.0
        elif greek(previous.strip()) and previous != previous.lstrip():
            value = continuation(s)
        elif '\ufffd' in previous:
            value = 0.55 * continuation(s)
        elif s in 'ρτλθκπφ':
            value = -0.045
        elif s in 'οωόήώ' or s == 'ου':
            value = 0.04
        elif s in 'αεη':
            value = -0.02
    return (doc, token), float(value)

programs.luna:
"""Use Greek script and the current word boundary as a small lexical cue.

This layer-0 component is unusually negative on many Greek letter pieces,
especially pieces that do not start with a space; word-start pieces and the
final Greek sigma are closer to zero.  The rule captures this broad average,
not the large changes in individual Greek contexts.
"""
import unicodedata

READS = ()


def greek_letters(token):
    return [c for c in token if c.isalpha()
            and "GREEK" in unicodedata.name(c, "")]


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    letters = greek_letters(token)
    if letters:
        if letters[-1] == "ς":
            return None, 0.01
        if token[:1].isspace():
            return None, -0.02
        return None, -0.07
    if "\ufffd" in token:
        return None, -0.023
    return None, 0.0

programs.sol:
"""Lexical 'add' detector, not an arithmetic calculator.

Forms of ADD get the largest response. Addition nouns, plus signs and related
insertion, inclusion, removal or creation words get smaller responses. Common
translations and add-prefixed code names are also recognized; long code names
are weaker. Simple English endings share a word-family response. The previous
token distinguishes 'in addition' and carries some response into an article or
word ending. Unmatched tokens predict zero; document boundaries reset context.
"""
import math
import re

READS = ()

# Roots of related English word families; inflections use the same small response.
ROOT_GROUPS = (
    (1.0, 'append insert subtract output'),
    (0.8, 'include contain provide bring brought attach join connect free '
          'delete push contribute'),
    (0.65, 'create creation apply input entry introduce missing attachment '
           'extract supplement extra plugin bonus'),
    (0.5, 'change update move connection contribution transfer submit exclude '
          'edit enter entries'),
    (0.35, 'set produce production supply'),
)
ROOT_GROUPS = [(value, frozenset(words.split())) for value, words in ROOT_GROUPS]


ADD_NOUNS = {
    'addition': 3.15, 'additions': 3.15,
    'additional': 1.7, 'additionally': 0.95,
    'additive': 2.85, 'additives': 2.85,
    'addon': 2.2, 'addons': 2.2,
}

TRANSLATIONS = (
    (5.2, 'добав добавить добавление 添 添加'),  # Russian add; Japanese/Chinese append
    (4.0, 'обав'),                             # continuation of Russian add root
    (2.6, 'ajout ajouter añ añad aggiung'),     # Romance-language add roots
    (2.3, '加 加入 加上'),                       # add / join / add onto
    (2.2, 'thêm'),                             # Vietnamese add/more
    (2.8, '新增'),                             # newly added
    (1.7, '增 増 增加'),                        # increase
    (1.2, 'дополн 附'),                        # supplement / attach
    (1.1, '更加'),                             # even more
    (0.7, '提供 输出 将 將 入 出 更 带 帶 送 除 除了 補 含 더 бонус'),
)
TRANSLATIONS = [(value, frozenset(words.split())) for value, words in TRANSLATIONS]


def word_roots(word):
    """A few familiar English plural and verb endings, not a full stemmer."""
    roots = {word}
    if word.endswith('s'):
        roots.add(word[:-1])
    if word.endswith('es'):
        roots.add(word[:-2])
    if word.endswith('ied'):
        roots.add(word[:-3] + 'y')
    for ending in ('ed', 'ing'):
        if word.endswith(ending):
            base = word[:-len(ending)]
            roots.update((base, base + 'e'))
            if len(base) > 1 and base[-1] == base[-2]:
                roots.add(base[:-1])
    if word.endswith('d'):
        roots.add(word[:-1])
    return roots


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lstrip('._(/#-').lower()
    value = 0.0

    if word == 'add':
        value = 4.7 if token.startswith('.') else 5.45
        if token.startswith('('):
            value = 4.0
    elif word in {'added', 'adding', 'adds'}:
        value = 4.8 if raw[:1].isspace() or word == 'adds' else 4.1
    elif word in ADD_NOUNS:
        value = ADD_NOUNS[word]
        if word == 'addition' and prev == 'in':
            value = 1.6
    elif word == 'plus':
        value = 0.95
    elif '+' in token:
        if '+=' in token:
            value = 1.2
        elif '++' in token and '+++' not in token:
            value = 0.4
        elif any(c.isalpha() for c in token):
            value = 0.35
        else:
            value = 0.7 if raw.startswith(' ') else 0.8
    elif re.match(r'add[A-Z]', token.lstrip('._(/#-')):
        # In longer camel-case method names, the root is less prominent.
        value = 5.4 * math.exp(-(len(word) - 3) / 8.0)
    elif token.endswith('Add'):
        value = 4.5
    elif word.startswith('add') and not word.startswith('addr'):
        value = 1.6
    elif word in {'remove', 'removes'}:
        value = 2.0 if token.startswith('.') else 1.6
    elif word in {'removed', 'removing', 'removable', 'removal'}:
        value = 1.15
    elif word in {'put', 'puts'}:
        value = 1.05 if token.startswith('.') else 0.72
    else:
        roots = word_roots(word)
        for strength, words in ROOT_GROUPS:
            if roots & words:
                value = strength
                break

    # Recognizable translations and partial roots of addition or manipulation.
    for strength, forms in TRANSLATIONS:
        if word in forms:
            value = strength
            break

    # Word completion and the immediate grammatical continuation of addition.
    if prev == 'add' and word in {'ition', 'itions', 'itive', 'itives'}:
        value = 3.4 if word.startswith('ition') else 2.0
    elif prev in {'добав', 'добавить', 'обав'} and word in {'ить', 'ление', 'лять'}:
        value = 2.0
    elif prev in {'add', 'added', 'adding', 'adds'}:
        if word in {'a', 'an'}:
            value = 1.05
        elif word == 'the':
            value = 0.75
        elif word in {'some', 'another'}:
            value = 0.7
    elif prev == 'addition':
        if word == 'of':
            value = 2.5
        elif word == 'to':
            value = -0.45
    return (doc, word), float(value)

programs.haiku:
"""Layer-0 MLP unit 5129 (down_proj): an 'add' detector.

It reads only the newest token. It fires hardest on the verb "add" in its plain forms
(add, Add, .add, adding, added, toadd): about 5 units. It is weaker on the noun
"addition" and "additional" (about 1.7), on plus signs (+, +=, plus: about 0.9), on the
same idea in other languages (加, 增加, добав...: about 2), and on the opposite verbs
remove / subtract / delete (about 1.5). A broader set of verbs about putting things into,
attaching, or supplying something (insert, append, push, put, include, provide, contain,
create, set, attach, join, connect, input, update, apply, contribute, bring, ...) gives a
weak 0.7. Everything else is 0.
"""

READS = ()

ADD_VERBS = {"add", "adding", "added", "adds", "toadd", ".add", "(add", "_add", "_added"}
ADDITION_WORDS = {"addition", "additional", "additionally", "additions", "additive", "additives"}
ADD_OTHER_LANGUAGES = {"加", "增加", "增", "増", "加入", "新增", "添加", "добав", "thêm"}
PLUS_SIGNS = {"+", "+=", "plus", ".+", ")+"}
REMOVE_WORDS = {"remove", "removed", "removing", "removes", ".remove", "toremove",
                "subtract", "delete", "删除"}
PUT_IN_WORDS = {"insert", ".insert", "append", ".append", "push", ".push", "put", ".put",
                "include", "includes", "including", "included", "provide", "provided",
                "provides", "providing", "contain", "contains", "containing", "create",
                "created", "creating", "output", "set", ".set", "attach", "attached",
                "input", "missing", "connect", "join", "joined", "update", "change",
                "changes", "apply", "free", "contribute", "contributed", "introduce",
                "introduced", "bring", "brought"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in ADD_VERBS:
        return None, 5.0
    if word in ADDITION_WORDS:
        return None, 1.7
    if word in ADD_OTHER_LANGUAGES:
        return None, 2.0
    if word in PLUS_SIGNS:
        return None, 0.9
    if word in REMOVE_WORDS:
        return None, 1.5
    if word in PUT_IN_WORDS:
        return None, 0.7
    return None, 0.0

programs.luna:
"""Flag plus and common verbs that add, make, move, or change something."""
READS = ()

ACTION_WORDS = {
    "add", "addition", "plus", "apply", "build", "change",
    "combine", "connect", "construct", "create", "delete",
    "enter", "expose", "fit", "give", "include", "insert",
    "join", "make", "move", "output", "pad", "produce",
    "provide", "put", "remove", "send", "set", "show",
    "submit", "take", "transfer", "turn", "update",
    "alter", "increase", "decrease", "replace", "write",
    "加", "将", "出", "进", "進", "变", "變", "增", "改",
}


def is_action(word):
    word = word.strip().lower().strip(".,;:!?()[]{}\"'")
    if word == "+" or word in ACTION_WORDS:
        return True
    forms = [word]
    if word.endswith("ies"):
        forms.append(word[:-3] + "y")
    for suffix in ("ing", "ed", "es", "s"):
        if word.endswith(suffix) and len(word) > len(suffix) + 1:
            root = word[:-len(suffix)]
            forms.extend((root, root + "e"))
            if len(root) > 2 and root[-1] == root[-2]:
                forms.extend((root[:-1], root[:-1] + "e"))
    return any(form in ACTION_WORDS for form in forms)


def step(carry, prefix, upstream):
    value = 0.7 if is_action(prefix.token_strings[-1]) else 0.0
    return None, value

programs.sol:
"""An O-letter detector with case and word-boundary sensitivity.

Capital Latin O is strongest at a document or word start, and weaker after
another capital (as in acronyms). Lowercase o is weaker inside a word.
Greek/Cyrillic lookalikes, circles, Japanese o syllables, oxygen spellings,
and short O clusters give related responses, but numeric zero does not.
Fragmented Unicode letters are recognized from decoded text. Other tokens
are assigned zero, leaving unrelated lexical responses unmodeled.
"""
READS = ()

# These glyphs either look like O or spell the Japanese syllable "o".
O_GLYPHS = {'ο': 1.05, '〇': 2.3, 'Ｏ': 1.2, 'ｏ': 0.7,
            'お': 0.46, 'オ': 0.64}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    completed = prefix.text_prefixes[-1][-1:] if '\ufffd' in token else ''
    word = token.strip()
    spaced = bool(token[:1].isspace())
    value = 0.0

    if completed in ('ο', 'Ο', 'ό', '〇'):
        value = {'ο': 3.4, 'Ο': 5.2, 'ό': 1.1, '〇': 2.3}[completed]
    elif word == 'O':
        if not previous:
            value = 4.2 if spaced else 5.5
        elif previous.isupper():
            value = 2.7 if spaced else 1.0
        elif spaced:
            value = 3.6
        elif previous.isspace():
            value = 4.4
        elif previous.isdigit():
            value = 3.2
        else:
            value = 3.6 if previous.islower() else 3.85
    elif word == 'o':
        if spaced:
            value = 1.35
        elif previous.islower():
            value = 0.26
        elif previous.isupper():
            value = 0.8
        else:
            value = 1.55
    elif word in ('О', 'Ο'):
        if not previous:
            value = 2.6
        else:
            value = 2.17 if spaced else 0.9 if previous.isupper() else 2.0
    elif word == 'о':
        value = 1.1 if spaced else 0.16 if previous.isalpha() else 0.7
    elif word == '○':
        value = 1.75 if spaced else 2.46
    elif word in O_GLYPHS:
        value = O_GLYPHS[word]
    elif (len(word) > 1 and word[-1] in 'Oo'
          and all(not c.isalnum() for c in word[:-1])):
        value = 1.8 if word[-1] == 'o' else 2.9 if word[-2] == '-' else 2.4
    elif word.lower() in ('oxygen', 'oxide'):
        value = 1.7 if spaced else 0.7
    elif word.startswith('氧'):
        value = 1.5  # Chinese oxygen / oxidation spellings.
    elif word.lower().startswith('ox'):
        value = 1.1 if word[0].isupper() or word.lower() == 'oxy' else 0.9
    elif word in ('Os', 'OS', 'os'):
        if word == 'Os':
            value = 1.0
        else:
            value = 0.75 if spaced else (0.03 if word == 'os' else 0.28)
    elif word.lower() == 'oo':
        value = 1.4 if word.isupper() else 0.55
    return (doc, completed or token[-1:]), value

programs.luna:
"""Approximates the sparse response to a one-letter O/omicron token.

A standalone Latin capital O is the strongest cue; lowercase o and the
visually related Greek and Cyrillic letter tokens have smaller responses.
"""
import unicodedata

READS = ()


def _letter_o(token):
    surface = token.strip()
    while surface and unicodedata.category(surface[0]).startswith("P"):
        surface = surface[1:]
    while surface and unicodedata.category(surface[-1]).startswith("P"):
        surface = surface[:-1]
    if len(surface) != 1:
        return None
    name = unicodedata.name(surface, "")
    if name.endswith("LETTER O") or name.endswith("LETTER OMICRON"):
        return surface
    return None


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    letter = _letter_o(token)
    if letter is None:
        return None, 0.0
    name = unicodedata.name(letter, "")
    if letter == "O":
        return None, 3.8
    if letter == "o":
        return None, 1.3 if token[:1].isspace() or len(token) > 1 else 0.3
    if "CAPITAL" in name:
        return None, 2.0
    return None, 1.1

programs.sol:
"""Approximate the component's lexical spikes, not its diffuse background.

Negative: cutting/truncation and temporal cutoffs (especially 截/截止).
Positive: specific report-writing and business-plan/person phrases.
The preceding token handles these phrases, particles in 'cut off/out',
and endings of Chinese compounds; state resets for each document.
"""
READS = ()

CUTOFFS = {
    '截': -4.2, '截至': -4.3, '截止': -4.7, '截至目前': -2.7,
    '剪': -1.95, '目前': -0.64, '目前为止': -2.0,
    '为止': -1.55, '至今': -0.73, 'cutoff': -1.55,
    'deadline': -1.35, 'deadlines': -1.07,
}
CUT = {'cut', 'cuts', 'cutting', '-cut', '_cut', 'cutt'}
SHORT_CUT_OR_TIME_TERMS = {'期限', '日期', '日至', '月至', '日起', '止', '切成', '切割'}
TRIMMING = {
    'trim', 'trimmed', 'trimming', 'clip', 'clips', 'clipping',
    'cutter', 'chop', 'chopped', 'trunc', 'truncate', 'truncated',
    'slash', 'slashing',
}
REPORT_TYPES = {
    'final', 'technical', 'official', 'medical', 'credit', 'consumer',
    'financial', 'sales', 'special',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    split_character = '\ufffd' in raw
    if split_character:
        char = prefix.text_prefixes[-1][-1:]
        if char in CUTOFFS:
            word = char
    value = CUTOFFS.get(word, 0.0)
    if word in CUT:
        value = -0.93 if word == 'cut' else -0.75
        if not raw[:1].isspace():
            value = -0.48
        if raw.strip() == 'Cut':
            value = -0.83
    elif word in SHORT_CUT_OR_TIME_TERMS:
        value = -0.5
    elif word.lstrip('.') in TRIMMING:
        value = -0.35
    elif word == 'scissors':
        value = -0.84
    elif word in {'off', '-off'}:
        value = -0.18
    elif old in REPORT_TYPES and word in {'report', 'reports', 'paper', 'papers'}:
        value = 0.65 + 0.2 * raw.strip().istitle()
    elif old == '毕业' and word == '论文':
        value = 1.0
    if old in CUT:
        scale = 0.75 if old == 'cutting' else 1.0
        if word in {'off', '-off'}:
            value = -1.85 * scale
        elif word in {'out', '-out', 'outs', 'up', 'down'}:
            value = -0.82 * scale
        elif word in {'into', 'from', 'short'}:
            value = -0.52 * scale
        elif word in {'ting', 'tings', 'ters', 'l', 'let', 'lets', 'est'}:
            value = -0.36 * scale
    elif old == '剪' and word in {'刀', '辑', '輯'}:
        value = -1.47
    elif old == '截止' and word in {'日期', '到'}:
        value = -3.2
    elif old == '截' and word == '取':
        value = -1.5
    elif old == 'business' and word in {'plan', 'plans', 'people', 'persons'}:
        value = 0.85
    return (doc, word), float(value)

programs.haiku:
"""Layer-0 MLP neuron-slot 5131 (down_proj): a "cut / cut-off / deadline" detector.

When the current token is a form of the English word "cut" (cut, cuts, cutting, Cut, cutter,
cut-off) it writes a clearly negative value; the same for the Chinese characters that mean
cut or cut-short (截, 剪) and the phrases built on them that mean "as of / up to a cut-off"
(截至, 截止, 目前为止). Weaker negative values for "deadline", "off" right after "cut", and
the Chinese "until" suffixes (止, 为止, 至). Everything else is 0.
Magnitudes are the average activation on the matching tokens in a training sample.
"""

READS = ()

CUT_EN = {"cut", "cuts", "cutting", "cutter", "cutback", "cutout"}
TRIM_EN = {"trim", "trimmed", "trimming", "clip"}
DEADLINE_EN = {"deadline", "deadlines", "cutoff"}
CUT_ZH = {"截": -3.8, "截至": -4.1, "截止": -4.1, "剪": -2.1, "剪辑": -2.1, "辑": -1.5}
UNTIL_ZH = {"目前": -0.7, "目前为止": -1.8, "为止": -1.3, "止": -0.7, "至": -0.4}


def word(token):
    return token.strip().lower().lstrip("-")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    w = word(token)
    if w in CUT_EN:
        return None, -0.9
    if w in DEADLINE_EN:
        return None, -1.3
    if w == "off" and word(prev) in CUT_EN:
        return None, -0.7
    if w == "off":
        return None, -0.2
    if w in TRIM_EN:
        return None, -0.4
    if token.strip() in CUT_ZH:
        return None, CUT_ZH[token.strip()]
    if token.strip() in UNTIL_ZH:
        return None, UNTIL_ZH[token.strip()]
    return None, 0.0

programs.luna:
"""Recognizes the split word family built on the English verb "cut".

A negative pulse marks the BPE piece "cut" and common literal forms such as
"cutting", "cuts", and "cutoff"; a smaller pulse marks a few continuations
that can finish a split form. Other text is predicted near zero.
"""
READS = ()


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1].strip().lower()
    forms = {"cut", "cuts", "cutting", "cutoff", "cut-off",
             "cutaway", "cutback", "cutlery"}
    if piece in forms or piece in {"目前", "日至", "止", "切成", "deadlines"}:
        return None, -0.9
    if piece.startswith("cut") and piece not in {"cute", "cutest", "cutely"}:
        if piece.endswith(("ting", "s", "off", "away", "back")):
            return None, -0.9
    previous = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if previous == "cut" and piece in {"ting", "back", "off", "away", "out", "on", "into", "the", "let", "est"}:
        return None, -0.3
    return None, 0.0014

programs.sol:
"""Recognize escaped quotes and the layout around conversation boundaries.

Backslash-escaped quotes give a large positive activation, with adjustments
for adjacent whitespace and opening/closing punctuation. Pure line breaks
are negative after chat, thinking, and tool markers; these boundary effects
are weaker near a document's beginning. Other line breaks are most negative
after many letters in the preceding token on a short line. Long whitespace
runs are weakly negative.
Markup tags have small fixed responses. Ordinary text is predicted as zero;
its smaller lexical variation is omitted.
"""
import math

READS = ()
TAG_VALUES = {
    '<think>': 0.13,
    '</tool_response>': 0.12,
    '<tool_call>': -0.06,
    '</tool_call>': -0.074,
    '<|im_end|>': 0.031,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous, position, line_length = '', '', 0, 0
    else:
        _, previous, before_previous, position, line_length = carry
    token = prefix.token_strings[-1]
    value = TAG_VALUES.get(token, 0.0)
    if '\\"' in token:
        left, _, right = token.partition('\\"')
        if not right:
            value = 1.80
            if left == ' ':
                value = 2.09
            elif '(' in left or '{' in left:
                value = 1.68
            elif '.' in left:
                value = 1.45
            elif '"' in left:
                value = 0.95
            elif not left and previous.endswith(('(', '[', '(f')):
                value = 2.15
            elif not left and '\\"' in previous:
                value = 1.60
        else:
            value = 1.0
            if right.startswith((')', ']', '>')):
                value = 0.85
            if right.startswith(',\\'):
                value = 0.53
            if right.startswith('/'):
                value = 1.19
    elif "\\'" in token:
        value = 0.93
    elif token and not token.strip(' \r\n'):
        nspaces = token.count(' ')
        if nspaces >= 12:
            value = -0.007 * min(nspaces, 32)
            # Four-space indents may share their last space with the next word.
            if nspaces % 4 == 3 and '\n' not in token:
                value *= 0.25
        elif token == ' \n':
            value = -0.025
        elif token == '\r':
            value = -0.093
        elif nspaces == 0:
            log_position = math.log1p(position)
            if previous == '<think>':
                value = -0.824 - 0.017 * log_position
            elif previous == '</think>':
                value = -0.755 - 0.030 * log_position
            elif previous == '<tool_response>':
                value = (-0.82 - 0.037 * log_position
                         + 0.52 / max(2, position))
            elif previous == '<tool_call>':
                value = -0.659 - 0.031 * log_position
            elif before_previous == '<|im_start|>':
                if previous == 'assistant':
                    value = -0.628 - 0.038 * log_position
                elif previous == 'user':
                    value = -0.545 + 0.785 / max(2, position)
            elif previous == '<|im_end|>':
                value = -0.75 if before_previous == '</tool_response>' else (
                    -0.57 if before_previous == '</tool_call>' else
                    -0.27 - 0.014 * sum(c.isalpha() for c in before_previous))
            else:
                letters = sum(c.isalpha() for c in previous)
                value = (0.043 - 0.022 * letters
                         + 0.0022 * min(line_length, 80)
                         - 0.015 * log_position)
    if '\n' in token:
        line_length = len(token.rsplit('\n', 1)[-1])
    else:
        line_length += len(token)
    return (doc, token, previous, position + 1, line_length), value

programs.luna:
"""Recognize line breaks and escaped quotes.

The predictor gives physical newlines a negative value, especially blank
lines and chat-role formatting. Escaped double quotes, frequent in code
strings, get a positive value.
"""
READS = ()
NEWLINE = chr(10)
BACKSLASH = chr(92)
ESCAPED_QUOTE = BACKSLASH + '"'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ""
    else:
        tail = carry[1]

    s = prefix.token_strings[-1]
    text = tail + s
    if s in (NEWLINE, NEWLINE * 2):
        recent = text[-100:]
        if s == NEWLINE * 2 or any(
            marker in recent
            for marker in ('<|im_start|>assistant', '<|think|>',
                           '</think>', '<|tool_response>')
        ):
            value = -0.9
        elif '<|im_end|>' in recent:
            value = -0.27
        else:
            value = 0.0
    elif s in (ESCAPED_QUOTE, ' ' + ESCAPED_QUOTE,
               '(' + ESCAPED_QUOTE):
        value = 2.1
    elif s == BACKSLASH + "'":
        value = 0.7
    else:
        value = 0.0

    return (doc, text[-160:]), float(value)

programs.haiku:
"""Program v4: a fixed negative value on a set of 'trouble' nouns (problem, error,
danger, damage, virus, toxic, ...), with 'problem' words more negative. Zero elsewhere."""
