programs.sol:
"""Lexical joining and affiliation, with a one-token grammatical continuation.

Join words (including code and SQL) give strong negative activations. Related
membership, participation, meeting, and entry words give weaker responses.
The signal also appears on complements such as 'member of' and 'joined the'.
This deliberately omits the component's small unrelated token-specific biases.
"""
READS = ()
JOIN = {'join', 'joins', 'joined', 'joining'}
MEMBER = {'member', 'members', 'membership', 'memberships'}
BELONG = {'belong', 'belongs', 'belonged', 'belonging'}
ENTER = {'enter', 'enters', 'entered', 'entering'}
PARTICIPATE = {
    'participate', 'participates', 'participated', 'participating', 'participation',
}
ATTEND = {'attend', 'attends', 'attended', 'attending'}
MEET = {'meet', 'meets', 'meeting', 'meetings'}


def stem(token):
    return token.strip().lstrip('._-(/').lower()


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    old = '' if start else carry[1]
    word, root, previous = token.strip(), stem(token), stem(old)
    value = 0.0
    if root in JOIN:
        value = {'join': -7.4, 'joins': -6.6, 'joined': -6.8, 'joining': -6.45}[root]
        if word == '.join':
            value = -8.5 if old == '.path' else -7.8 if previous == 'path' else -5.5
        elif word == '.Join':
            value = -6.5 if 'path' in old.lower() else -4.9
        elif word.isupper():
            value = -8.25 if token.startswith(' ') else -6.85
        elif word.startswith('_') or token in {'join', 'joined'}:
            value = -5.8
        elif word == 'Joined':
            value = -7.6
        if start and word == 'Join':
            value = -10.58
    elif root in MEMBER:
        value = -1.0 if root.startswith('membership') else -0.67
    elif root in BELONG:
        value = -0.93
    elif root in ENTER:
        value = -0.9 if token.startswith(' ') else -0.45
    elif root in PARTICIPATE:
        value = -1.05
    elif root in ATTEND:
        value = -1.3
    elif root in MEET:
