    elif word in {'加入', '参加', '參加', '加盟'}:
        value = -3.5
    elif word in {'参与', '參與', '进入', '進入', '出席', '报名', '報名', '加'}:
        value = -1.1
    elif word == '入':
        value = -3.5 if old.strip() == '加' else -0.7

    # Recognize words split into tokens, such as Jo|ins or Join|ing.
    if old and token[:1].isalpha() and stem(old + token) in JOIN and root not in JOIN:
        value = -6.1 if previous not in JOIN or old.strip().startswith('J') else -3.5

    if word == 'of' and previous in MEMBER:
        value = -1.4 if previous == 'members' else -2.2
    elif word == 'to' and previous in BELONG:
        value = -1.55 if previous == 'belonging' else -1.8
    elif word == 'in' and previous in BELONG | PARTICIPATE:
        value = -0.97 if previous in BELONG else -0.6
    elif word == 'the' and previous in ENTER | MEET | ATTEND:
        value = -0.43
    elif previous in JOIN:
        capital = old.strip().startswith('J') and not old.strip().isupper()
        if word == ':' and previous == 'joined':
