"""Layer-0 MLP component 5135 (down_proj): a "joining / belonging" detector.

Plain terms: the component goes negative in text about joining a group or
belonging to one. Its strongest response is to the word "join" in any form
(join, Join, joined, joins, joining, and ".join" as in a code method call),
which pushes it to about -7 to -8. Weaker responses (about -1) come on verbs
of entering or attending (enter, entering, attend, belong, belongs), and on
Chinese characters for entering or joining (入, 进, 加). Membership nouns
(member, members) sit around -0.6. The strongest of the mild responses is on
the preposition that completes a membership phrase: "of" in "member of" (about
-2.2) and "to" in "belongs to" (about -1.9). Everywhere else it is near zero.
"""

READS = ()

JOIN_WORDS = {"join", "joined", "joins", "joining"}
ENTER_WORDS = {"enter", "entered", "enters", "entering", "attend", "attended", "attends", "attending",
               "belong", "belongs", "belonged", "belonging"}
MEMBER_WORDS = {"member", "members"}
ENTER_CHARS = {"入", "进", "加"}

JOIN_VALUE = -7.5
ENTER_VALUE = -0.9
MEMBER_VALUE = -0.6
CHAR_VALUE = -0.9
MEMBER_OF_VALUE = -2.2
BELONG_TO_VALUE = -1.9


def word(token_string):
    """A token's word: lowercase, without surrounding spaces or dots."""
    return token_string.strip().strip(".").lower()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    current = word(raw)
    value = 0.0
    if current in JOIN_WORDS:
        value = JOIN_VALUE
    elif current in ENTER_WORDS:
        value = ENTER_VALUE
    elif current in MEMBER_WORDS:
        value = MEMBER_VALUE
    elif raw.strip() in ENTER_CHARS:
        value = CHAR_VALUE
    same_document = len(prefix) >= 2 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if same_document:
        previous = word(prefix.token_strings[-2])
        if current == "of" and previous in MEMBER_WORDS:
            value = MEMBER_OF_VALUE
        elif current == "to" and previous in {"belong", "belongs", "belonged", "belonging"}:
            value = BELONG_TO_VALUE
    return None, float(value)

