    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    for lang in CLUES.get(lower, ()):
        scores[lang] = scores.get(lang, 0.0) + 1.0
    for lang, letters in DISTINCTIVE_CHARACTERS.items():
