"""Ability and capacity words give a negative activation.

The largest response is to 'ability', 'capability', and Chinese 能力.
Related capacities, dispositions, limitations, and '-ability' endings
respond more weakly. The negative response can continue onto a connecting
'of', 'to', or 'for'. 'Already' is a small positive exception.
This deliberately leaves weaker, unrelated lexical responses at zero.
"""
READS = ()

CAPACITIES = {'capacity', 'capacities', 'skill', 'skills', 'facility',
              'facilities', 'opportunity', 'opportunities', 'utility',
              'utilities', 'possibility', 'stability'}
DISPOSITIONS = {'tendency', 'tendencies', 'propensity', 'availability',
                'mobility', 'instability', 'volatility', 'susceptibility'}
LIMITS = {'difficulty', 'difficulties', 'limitation', 'limitations',
          'obligation', 'obligations', 'responsibility', 'responsibilities',
          'desire', 'talent', 'talents', 'impairment', 'tolerance'}
ENDINGS = {'abil', 'ility', 'ibility', 'ibilities', 'abilité', 'abilidad',
           'abilidade', 'ibilidade'}
ALREADY = {'already', 'уже', 'schon', 'bereits', 'すでに', 'già', 'już'}


def lexical(raw, previous):
    word = raw.strip().lower()
    if word == 'ability':
        if raw[:1].isspace():
            if previous in {'the', 'an'}:
                return -5.3
            if previous in {'my', 'our', 'his', 'her', 'your'}:
                return -4.4
            return -4.9
        return -4.0 if raw == 'Ability' else -1.9
    if word == 'abilities':
        return -3.6 if raw[:1].isspace() else -1.6
    if word in {'capability', 'inability'}:
        return -3.4
    if word == 'capabilities':
        return -2.6
    if word in {'disability', 'disabilities', 'willingness'}:
        return -1.9
    if word in {'能力', '的能力'}:
        return -3.7
    if '能力' in word:
        return -2.7
    if word in {'variability', 'abilit', 'ibilit'}:
        return -1.5
    if word in {'flexibility', 'functionality', 'versatility'}:
        return -1.3
    if word in ENDINGS or word in DISPOSITIONS:
        return -1.0
    if word in CAPACITIES or word in {'技能', '功能', '潜力', '灵活性'}:
        return -0.8
    if word in {'probability', 'accountability', 'eligibility'}:
        return -0.3
    if word.endswith(('ability', 'abilities', 'ibility', 'ibilities', 'ility')):
        return -0.7
    if word in LIMITS:
        return -0.55
    if word in {'able', 'unable'}:
        return -0.6 if raw[:1].isspace() else -0.1
    if word in {'disabled', 'disable', 'capable', 'potential'}:
        return -0.3
    if word in ALREADY:
        return 0.55
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, strength, whole = '', 0.0, False
    else:
        _, previous, strength, whole = carry
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    base = lexical(raw, previous)
    value = base
    if word in {'of', 'to', 'for'}:
        if previous in {'ability', 'capability', 'inability'} and whole:
            value += strength * {'of': 0.46, 'to': 0.23, 'for': 0.15}[word]
        elif previous in {'capacity', 'potential', 'power'}:
            value -= 0.5 if word == 'of' and previous == 'capacity' else 0.25
        elif strength < -0.3:
            fraction = 0.35 if whole and word == 'of' else 0.12
            if word == 'to' and previous in {'able', 'opportunity', 'desire'}:
                fraction = 0.27
            value += strength * fraction
    # A leading space or capital approximates the beginning of a word.
    whole = raw[:1].isspace() or raw[:1].isupper()
    return (doc, word, base, whole), float(value)

"""A negative spelling response, strongest on short 'di' fragments.

Standalone d, di-/dy- word beginnings, and a few non-Latin di/ji spellings
also respond. Longer tokens usually weaken the response; technical roots
such as digit-, diag-, dimen-, and dyn- retain more of it. These rules use
only the current token, not its meaning or preceding context.
"""
import math

READS = ()

DI_JI_SPELLINGS = {
    'ディ': -3.15, 'ジ': -2.65, 'じ': -1.3,
    '디': -2.3, 'دي': -2.1, '迪': -4.1,
}


def fade(strength, length, start, rate):
    return -strength * math.exp(-rate * max(0, length - start))


def spelling_response(text):
    bare = text.strip()
    word = bare.lstrip('._-/(:<*').lower().rstrip('.,:;!?\'"()[]{}')
    n = len(word)
    spaced = text[:1].isspace()
    if bare in DI_JI_SPELLINGS:
        return DI_JI_SPELLINGS[bare]
    if word == 'ди':
        return -3.8 if spaced else -1.6
    if word.startswith('ди'):
        return fade(1.7, n, 3, 0.20)
    if word == 'd':
        value = -0.56 if 'D' in bare else -0.4
        return value - (0.06 if spaced else 0.16 if bare[:1] in '._-/' else 0)
    if word == 'di':
        value = -5.0 if 'Di' in bare else -4.25 if 'DI' in bare else -3.6
        return value - (0.85 if bare[:1] in '._-/' else 0)
    if word in ('dí', 'dì', 'dı', 'dī'):
        return -1.9
    if word in ('dx', 'ds'):
        return -0.5
    if word == 'dy':
        return -1.3
    if word == 'dis':
        return -2.25
    if word == 'dit':
        return -1.65 if spaced else -2.4
    # Common auxiliary/article forms are weak despite their spelling.
    if word in ('did', 'die'):
        return -0.3
    if word.startswith('didn'):
        return 0.0
    if word.startswith(('di', 'dy')):
        if word.startswith('distan'):
            return -0.65
        if word.startswith(('diag', 'digit', 'dimen', 'dyn')):
            return fade(1.6, n, 4, 0.09)
        if word.startswith('dia'):
            return fade(1.4, n, 3, 0.12)
        if word.startswith(('disc', 'disk')) or word == 'dys':
            return -0.35 if word != 'dys' else -0.9
        if n == 3:
            return -1.0 if word[-1] in 'rmv' else -1.7
        return fade(0.9, n, 4, 0.45)
    if word.startswith('edit'):
        return fade(1.0, n, 4, 0.10)
    # Internal di is stronger in short continuation fragments than whole words.
    if not spaced and not bare[:1].isupper():
        if 'di' in word and 'ddi' not in word:
            offset = word.index('di')
            return fade(1.7, n, 3, 0.5) * math.exp(-0.45 * max(0, offset - 1))
        if word.endswith('dy'):
            return -1.0 if n == 3 else -0.25
    return -0.001


def step(carry, prefix, upstream):
    return None, float(spelling_response(prefix.token_strings[-1]))

