# The syllable "di" written in other scripts (Cyrillic, katakana, Chinese).
DI_SYLLABLE_OTHER_SCRIPTS = {"ди", "迪", "ディ", "ジ"}


def step(carry, prefix, upstream):
    word = "".join(c for c in prefix.token_strings[-1].lower() if c.isalpha())
    if word == "di" or word in DI_SYLLABLE_OTHER_SCRIPTS:
        value = -3.7  # the bare syllable
    elif word == "d":
        value = -0.5  # a lone letter d
    elif word == "die":
        value = -0.3  # German article "die" is weak
    elif word.startswith("di") and len(word) <= 5:
        value = -0.9  # short di-fragments: dis, dig, dit, div, digit
    elif word.startswith("di"):
        value = -0.3  # longer di-words
    elif word.startswith("dy"):
        value = -1.0  # dy, dyn, dynamic
    elif "edit" in word:
        value = -0.9  # "di" inside edit/editor
    elif "di" in word:
        value = -0.1  # "di" elsewhere in a word, barely active
    else:
        value = 0.0
    return carry, float(value)

