"""A short-'et' spelling detector, with weaker responses to familiar words.

Short et / -et fragments respond most; extra letters usually dilute the
response. Common words get, set, let, met and yet have reduced strengths.
Cyrillic/accented et spellings and set/asset translations partly share it.
For spaced 'et', recent French versus English function words distinguish
the French conjunction from the stronger response in English citations.
"""

READS = ()
FRENCH = frozenset('le la les des du un une est que qui dans pour pas sur au '
                   'aux en ce ces se ne il elle avec vous nous mais par son sont'.split())
ENGLISH = frozenset('the of to and in is for that it on with as was are this '
                   'by be from not at or an have has we they but'.split())
# Whole-word and unspaced-fragment estimates for frequent short -et forms.
COMMON_ET = {
    'get': (1.0, 1.45), 'set': (0.9, 1.3), 'let': (1.8, 2.4),
    'met': (0.9, 1.5), 'yet': (1.3, 2.3),
    'ret': (1.55, 2.0), 'det': (2.35, 3.0),
}


def spelling_response(raw):
    word = raw.strip().strip('._/-(\"\'')
    w = word.lower()
    spaced = raw.startswith(' ')
    if w == 'et':
        if word == 'Et':
            return 2.1
        return 3.8 if word.isupper() else (2.5 if spaced else 3.4)
    if w in COMMON_ET:
        if w == 'let' and word[0].isupper():
            return 1.6
        if w in {'get', 'set'} and raw.startswith('.'):
            return 1.25
        if w in {'get', 'set'} and raw.startswith('/'):
            return 1.7 if w == 'get' else 2.2
        if w in {'get', 'set', 'met'} and word.isupper():
            return 1.8
        return COMMON_ET[w][0 if spaced else 1]
    if len(w) == 3 and w.endswith('et'):
        return 3.1
    if w in {'ets', 'ett'}:
        return 2.9 if w == 'ets' else 1.8
    if len(w) == 4 and w.endswith('ets'):
        return 0.75 * COMMON_ET.get(w[:-1], (3.0, 3.0))[0]
    if w == 'etc':
        return 0.0
    if w.startswith('et'):
        if w.startswith(('etic', 'etal', 'ety', 'etta', 'ette', 'etch')):
            return 1.65 if len(w) <= 5 else 0.4
        return 1.1 if len(w) == 3 else 0.45
    if 'et' in w:
        if w.startswith('asset'):
            return 1.2 if spaced else 1.65
        if w.startswith(('getting', 'letting', 'betting')):
