"""Sparse spelling/word-class approximation of this component.

Indic dental t/d have positive bases; retroflex T/D have negative bases.
Each repetition of the same stop token in the preceding 16 tokens subtracts
0.2. Split UTF-8 bytes have additional signed responses, and a few other
scripts' t/d spellings get smaller responses. These patterns stood out in
training; most weaker, token-specific responses are left at zero.

Small baselines cover the listed space-prefixed word classes, code/chat
markers, and the colon of a document-opening 'Title:' header. State resets
at document boundaries. No upstream components are used.
"""
import unicodedata

READS = ()
# Qwen's first 256 vocabulary entries encode individual bytes, in this order.
_VISIBLE = tuple(range(33, 127)) + tuple(range(161, 173)) + tuple(range(174, 256))
BYTE_ALPHABET = _VISIBLE + tuple(b for b in range(256) if b not in _VISIBLE)
INDIC = (
    'DEVANAGARI', 'BENGALI', 'GURMUKHI', 'GUJARATI', 'ORIYA',
    'TAMIL', 'TELUGU', 'KANNADA', 'MALAYALAM',
)


# Small word classes, with averaged responses rather than per-token lookup.
WORD_CLASSES = (
    # Obligation, ability, and negation.
    (frozenset('must should shall ought'.split()), 0.052),
    (frozenset('can'.split()), 0.026),
    (frozenset('not without'.split()), 0.032),
    # Spatial relations, first-person objects/possessives, and memory verbs.
    (frozenset(
        'inside within between among above below outside around over'.split()
    ), -0.041),
    (frozenset('me my mine myself'.split()), 0.033),
    (frozenset('know understand remember forget'.split()), 0.064),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, recent = 0, '', ()
    else:
        _, position, previous, recent = carry
    token = prefix.token_strings[-1]
    text = token.strip()
    value = 0.0
    if token.startswith(' '):
        for words, response in WORD_CLASSES:
            if text in words:
                value = response
                break
    if text == '__':
        value = 0.058
    elif token == ' {"':
        value = 0.066
    elif token == '<tool_call>':
        value = 0.116
    elif token == '</tool_call>':
        value = -0.056
    elif token == '</think>':
        value = -0.139
    elif token == '<|im_end|>':
        value = 0.042
    if token == ':' and position == 1 and previous == 'Title':
        value = 0.52
    split = '\ufffd' in token
    if split:
        # Joined decoding distinguishes an unfinished byte sequence from a
        # character completed by this token. Do not borrow across a new doc.
        text = (token[-1:] if position == 0
                else prefix.text_prefixes[-1][-1:])
        i = int(prefix.token_ids[-1])
        byte = BYTE_ALPHABET[i] if 0 <= i < 256 else None
        if text == '\ufffd':
            if byte in (0xa4, 0xa6):
                value = 0.7 if byte == 0xa4 else 0.9
            elif byte in (0xa1, 0x9f, 0xd9):
                value = -0.7 if byte == 0x9f else -0.45
        elif byte == 0xa6:
            value = 0.2
        elif byte in (0xa1, 0x9f):
            value = -0.08
            # Greek and Greek Extended Unicode blocks.
            greek = (0x370 <= ord(text) <= 0x3ff
                     or 0x1f00 <= ord(text) <= 0x1fff)
            if greek:
                value = -0.4 if byte == 0x9f else -0.18
        if byte == 0xa6 and 0x370 <= ord(text) <= 0x3ff:
            value = 0.07
    if len(text) == 1:
        name = unicodedata.name(text, '')
        if name.startswith(INDIC):
            repeats = 0.2 * recent.count(prefix.token_ids[-1])
            if name.endswith(' LETTER TA'):
                value = 1.6 - 0.16 * split - repeats
            elif name.endswith(' LETTER DA'):
                value = 1.84 - 0.16 * split - repeats
            elif name.endswith((' LETTER TTA', ' LETTER DDA')):
                value = -1.3 - 0.16 * split - repeats
        elif text in 'τΤδ':
            value = 0.2 if split else 0.14
        elif text in 'ṭḍט':
            value = -0.55
        elif text in 'تد':  # Plain Arabic dental t/d.
            value = 0.083
        elif text in 'תד':  # Plain Hebrew t/d, versus emphatic tet above.
            value = 0.18
    recent = (recent + (prefix.token_ids[-1],))[-16:]
    return (doc, position + 1, token, recent), value

