"""Straight-quote novelty, with a weaker response after recent quotes.

Apostrophes starting contractions/elisions and opening quotation marks have
negative activation. The response grows with the time since the same kind
of quote was last used. Closing and code-delimiter tokens have smaller
responses. Curly right quotation marks have a small positive response.

This approximates the dominant quote response, not the small fluctuations
on ordinary words. Quote gaps are capped at 512 tokens; state resets when
the document changes. At its first token, the quote response is weakened.
"""
import math

READS = ()
PERSONAL_ENDINGS = {"'m", "'ll", "'ve", "'d"}


def quote_response(s):
    """Return the baseline and the extra response to an unfamiliar quote."""
    if s.startswith("'") and s[1:].isalpha():
        if s in PERSONAL_ENDINGS:
            return -0.40, -1.24
        if s == "'re":
            return -0.13, -1.10
        return -0.35, -0.89
    if s.startswith('"') and s[1:].isalpha():
        return -0.13, -0.67
    if s == "'":
        return 0.01, -1.24
    if s == '"':
        return 0.06, -1.05
    if s.strip() in {"'", '"'}:
        if s[0].isspace():
            return (-0.43, -0.65) if "'" in s else (-0.54, -0.45)
        return 0.09, -0.44  # quote followed by a line break
    if s.strip() in {"('", '("'}:
        return (-0.55, -0.23) if "'" in s else (-0.53, -0.35)
    if s in {"='", '="', ":'", ':"', "{'", '{"'}:
        return -0.28, -0.18
    if s in {"['", '["'}:
        return -0.05, -0.32
    if '\\' in s:
        return 0.0, 0.0
    if s[-1:] in {"'", '"'} and s[:-1].strip() in {
        '.', ',', '!', '?', ';', ':', '>', '<<'
    }:
        return 0.10, -0.60
    return 0.10, -0.33  # other merged quote/punctuation tokens


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, -10000, -10000)
    _, position, single, double = carry
    s = prefix.token_strings[-1]
    value = 0.0
    if "'" in s or '"' in s:
        last = single if "'" in s else double
        gap = min(512, position - last)
        novelty = math.log1p(gap) / math.log(513)
        base, strength = quote_response(s)
        value = base + strength * novelty
        if position == 0 and (base != 0.0 or strength != 0.0):
            value += 0.70
        if "'" in s:
            single = position
        if '"' in s:
            double = position
    elif '”' in s:
        value = 0.12
    return (doc, position + 1, single, double), float(value)

