            value = -6.4 if spaced else -3.1
        elif capital:
            value = -8.0 if spaced else -6.8
        else:
            value = -6.7 if spaced else -4.8
    elif lower == 'words':
        value = -2.0 if prev == 'other' else (-3.25 if capital else -2.85)
    elif lower == 'wordpress':
