def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, 0, 0)
    _, previous, position, line_endings, cr_run = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    stem = word.lower()
    subject = previous.strip().strip('"')
    lower_subject = subject.lower()
    n_crlf = token.count('\r\n')
    value = 0.0
    if token == '\r':
        value = -8.5 - 0.4 / (1.0 + cr_run)
        if previous.endswith('\n'):
            value = -8.0
        elif previous == '\x00':
            value = -10.1
        if position == cr_run:
            value = -9.5
    elif n_crlf:
        core = token.replace('\r\n', '')
        if token.strip('\r\n') == '' and token.count('\r') > n_crlf:
            extra = token.count('\r') - n_crlf
            value = -1.14 / extra ** 1.6
        else:
            if n_crlf > 1 or not core or core.isspace():
                value = 0.18 if not core else 0.20
            elif core == ';':
                value = 0.38
            elif core.strip().endswith((';', ':', '{', '}', ')', ',')):
                value = 0.26
            elif core.strip() in {'.', '!', '?'}:
                value = 0.11
            else:
                value = 0.20
            value -= 0.49 / (1.0 + line_endings)
            value += 0.15 / (1.0 + position)
            # In long, sparsely broken text, a CRLF remains a negative cue.
            value -= 0.39 * (position + 1) / (
                position + 1 + 30 * (line_endings + 1)
            )
    elif token == '__(':
        # Closing a Python dunder method name and opening its arguments.
        value = -1.47 if previous == 'init' else -0.65
    elif token == 'equ':
        # The beginning of equation, usually in a LaTeX environment name.
        value = -0.94 if previous == '{' else -0.38
    elif stem in NEGATED_AUXILIARIES:
        value = NEGATED_AUXILIARIES[stem]
        if word != stem or not token.startswith(' '):
            value *= 0.43
        else:
            # Subject and capitalization cues, not a lookahead for the apostrophe.
            scale = 0.35 if stem == 'won' else 1.0
            adjustment = 0.0
            if subject == 'I':
                adjustment = -0.32
            elif lower_subject == 'we':
                adjustment = -0.18
            elif lower_subject == 'you':
                adjustment = -0.12
            elif lower_subject in {'he', 'she', 'it', 'they'}:
                adjustment = -0.03
            elif lower_subject in {'this', 'that', 'these', 'those'}:
                adjustment = -0.07
            elif lower_subject in {'and', 'or', 'but'} or subject == ',':
                adjustment = 0.17
            if subject[:1].isupper() and lower_subject in {
                'we', 'you', 'he', 'she', 'it', 'they', 'this', 'that',
            }:
                adjustment -= 0.18
            value += scale * adjustment
    return (
        doc, token, position + 1, line_endings + n_crlf,
        cr_run + 1 if token == '\r' else 0,
    ), value

