"""A spelling-family detector, strongest for comm-, command and community.

Inflected forms generally have smaller responses. Recommendations and several
translations of community, committee and recommendation are also recognized.
A few split-word endings and "community of" use the preceding token.
This does not classify a sentence's intent.
"""
READS = ()


def response(token):
    word = token.lstrip(' \t\r\n._/-').lower()
    capitalized = token.lstrip(' \t\r\n._/-')[:1].isupper()
    attached = token.startswith(('.', '/', '_'))
    if word == 'comm':
        return 5.3
    if word == 'com':
        return 0.6 if capitalized or token.startswith('_') else 0.15
    if word == 'cmd':
        return 1.25 if not token.startswith('/') else 0.6
    if word.startswith('command'):
        if word == 'command':
            return 3.1 if not token.startswith(' ') else 2.9
        if word == 'commands':
            return 2.5 if capitalized else 2.0
        return 1.1
    if word.startswith('communit'):
        return 3.0 if word.endswith('ies') else 3.5
    if word.startswith('commiss'):
        if word == 'commission':
            return 2.9
        if word.endswith('er'):
            return 1.6
        return 2.1
    if word.startswith('committ'):
        if word.startswith('committee'):
            return (2.0 if capitalized else 1.5) - (0.3 if word.endswith('s') else 0.0)
        return 2.0
    if word.startswith('commit'):
        if word.startswith('commitment'):
            return 1.5 if word.endswith('s') else 2.05
        if word == 'commit' and not token.startswith(' '):
            return 1.95 if token.startswith('.') else 3.6
        return 2.5
    if word.startswith('common'):
        if word == 'commonly':
            return 1.0
        if word != 'common':
            return 1.4
        return 1.3 if attached else 2.0
    if word.startswith('comment'):
        if word.endswith('s') or word in ('commented', 'commentary'):
            return 0.75
        if word == 'comment':
            return 1.7 if capitalized else (1.3 if token.startswith(' ') else 2.1)
        return 1.3
    if word.startswith('communic'):
        return 0.9 if word.endswith('s') and not capitalized else 1.6
    if word.startswith('commun'):
        return 2.5
    if word.startswith('commut') or word.startswith('comma'):
        return 2.5 if word in ('commute', 'commuting', 'comma') else 1.6
    if word.startswith('commend'):
        return 2.4
    if word.startswith('commenc'):
        return 0.85
    if word.startswith('commerc'):
        return 0.1 if word.startswith('commercial') else 0.45
    if word == 'comme':
        return 0.2
    if word.startswith('comm'):
        return 0.7
    if word.startswith('recommend'):
        if word.endswith('ations'):
            return 2.3
        if word.endswith('ed'):
            return 2.95
        if word.endswith('s'):
            return 2.6
        return 3.4 if word.endswith('ing') else 3.7
    if word.startswith(('recomen', 'recommand')):
        return 2.7
    # Romance common/community roots and Russian command.
    if word.startswith(('comun', 'común', 'команд')):
        return 2.0
    if word == 'komm':
        return 2.5
    if word.startswith('kommun'):
        return 1.7
    if word.startswith('komment') or word == 'ком':
        return 1.0
    if word == 'kom':
        return 0.85
    if word.startswith(('gemein', 'geme')):
        return 0.8
    if word.startswith('remote'):
        return 1.0
    if word.startswith('encourag'):
        return 0.75
    if word.startswith('compress'):
        return 0.65
    if word.startswith('collabor'):
        return 0.6
    # Chinese community, committee, recommendation, and shared/common words.
    if word in ('社区', '社區'):
        return 2.3
    if word == '委':
        return 3.9
    if word in ('委员会', '委員会'):
        return 1.6
    if word in ('推荐', '推薦'):
        return 2.0
    if word in ('共同', '共', '共产党', '纪委'):
        return 0.95
    # Advice, encouragement, and communication.
    if word in ('建议', '建議', '鼓励', '通信', '通讯', '沟通'):
        return 0.75
    # Japanese recommendation and community spellings.
    if word in ('おすすめ', 'オススメ') or word.startswith('コミュニ'):
        return 1.6
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.lstrip(' \t\r\n._/-').lower()
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    value = response(token)

    # A root and its ending can occupy separate tokens.
    if token.isalpha():
        if previous == 'comm':
            value = 0.9
            if word in ('ute', 'ends', 'ending', 'its'):
                value = 2.0
            elif word in ('enced', 'encing', 'ended', 'utes'):
                value = 1.6
            elif word in ('une', 'unit', 'otion'):
                value = 0.3
        elif previous in ('recommend', 'recomm') and word.startswith('ation'):
            value = 2.8
        elif previous == 'communic' and word.startswith(('at', 'ate')):
            value = 1.3
        elif previous == 'commit' and word.startswith(('ment', 'tee')):
            value = 0.85

    # The construction "community of ..." retains a little response on "of".
    if word == 'of' and previous in ('community', 'communities'):
        value = 1.05
    return (document, word), float(value)

