READS = ()

BODY_AND_NATURE = frozenset({
    "bark", "thigh", "hair", "neck", "knee", "skin", "fish", "wing",
    "tail", "eye", "eyes", "egg", "limestone", "cavity",
})

FOOD = frozenset({
    "salad", "steak", "egg", "nut", "cashew", "butter", "noodle",
    "ingredient", "paprika", "sugar", "fish", "tea",
})

TOOLS_AND_MATERIALS = frozenset({
    "rail", "balloon", "cord", "brace", "scissor", "hole", "cartridge",
    "cradle", "tripod", "ring", "shirt", "washer", "earring", "belt",
    "sink", "paper", "box", "plate", "sensor", "barograph", "material",
    "cylinder", "pipe", "nail", "plug", "blade", "molding", "paint",
    "diaper", "compost", "conveyor", "ball", "joint", "bumper", "tail",
    "bag", "stair", "chair", "ice", "bolt", "hose", "steel", "stainless",
    "sheet", "duct", "laser", "beam", "nailplate", "wood", "glass", "stone",
})

PHYSICAL_ACTIONS = frozenset({
    "fold", "glue", "glued", "clean", "prepare", "cut", "dry", "shake",
})

TRIGGERS = BODY_AND_NATURE | FOOD | TOOLS_AND_MATERIALS | PHYSICAL_ACTIONS
BACKGROUND = -0.0072
OBJECT_RESPONSE = -0.42


def matches(word):
    if word in TRIGGERS:
        return True
    if word.endswith("es") and word[:-2] in TRIGGERS:
        return True
    if word.endswith("s") and word[:-1] in TRIGGERS:
        return True
    if word.endswith("ing"):
        stem = word[:-3]
        roots = {stem, stem + "e"}
        if len(stem) > 2 and stem[-1] == stem[-2]:
            roots.add(stem[:-1])
        if roots & TRIGGERS:
            return True
    if word.endswith("ed"):
        stem = word[:-2]
        if stem in TRIGGERS or stem + "e" in TRIGGERS:
            return True
    return False


