    "does", "did", "got", "gave", "given", "knew", "thought", "took",
    "saw", "came", "felt", "became", "left", "kept", "began", "showed",
    "ran", "held", "brought", "wrote", "withdrew", "fled", "meant",
})


def known_verb(word):
    if word in VERBS or word in IRREGULAR:
        return True
    if word.endswith("s") and word[:-1] in VERBS:
        return True
    if word.endswith("es") and word[:-2] in VERBS:
        return True
    if word.endswith("ed") and (word[:-2] in VERBS or word[:-1] in VERBS):
        return True
    if word.endswith("ing") and (
        word[:-3] in VERBS or word[:-3] + "e" in VERBS
    ):
        return True
    return False


def step(carry, prefix, upstream):
    doc, word = carry if carry is not None else (None, "")
    here = prefix.document_ids[-1]
    if doc != here:
        word = ""

    piece = prefix.token_strings[-1]
    if any(ch.isspace() for ch in piece):
        word = piece.split()[-1] if piece.split() else ""
    else:
