programs.sol:
"""A signed detector of closing-punctuation clusters, not ordinary words.

Expression/bracket endings usually score positively. Quotes followed by commas,
semicolons or line breaks tend to score negatively. A recent matching quote
raises compound-quote scores, especially when introduced after a space.
Small adjustments cover empty/decorative quotes, extra line breaks, neighboring
punctuation, and early document positions; all state resets between documents.
This is a coarse approximation: it omits word-specific activation differences.
"""
READS = ()
QUOTE_GROUPS = ("'‘’", '"“”', '`')
CLOSING_QUOTES = "'\"’”`"

# Recognizable punctuation combinations, ordered from specific to general.
ENDINGS = (
    ('%)', 1.2),       # Percentage inside parentheses.
    ('%.', 0.7),
    ('++)', 0.95),     # Increment at the end of an expression.
    ('[])', 1.15),     # Empty container at the end of an expression.
    ('{})', 1.15),
    ('())', 0.7),      # Empty call followed by another closing parenthesis.
    ('().', 0.35),
    ('__.', 0.35),     # Underscored identifier endings.
    ('__/', 0.35),
    ('.)', 0.5),       # Punctuation inside a closing parenthesis.
    ('].', 0.4),
    ('])', 0.35),
    ('})', 0.25),
    ('}.', 0.25),
    ('};', 0.25),
)


def unquoted_ending(s, t):
    for marks, value in ENDINGS:
        if marks in t:
            return value
    if t.startswith('()'):
        return 0.1 if ';' in t else 0.0
    if t == '++':
        return 0.25
    if any(mark + ')' in t for mark in '?!*+/>'):
        return 0.65
    if t.startswith(']') and ',' in t:
        return 0.15
    if t in ('」', '』'):
        return -0.15
    if t.startswith('/>'):
        return 0.7
    if '\n' in s:
        return {')': -0.05, ');': -0.1, ';': -0.05, '/': -0.1,
                '*': -0.3, '}': 0.05, ']': 0.1}.get(t, 0.0)
    return 0.0


def quoted_ending(s, t, q):
    """None means this is not a compound quote ending."""
    tail, before = t[q+1:], t[:q]
    if t in ('"""', "'''", '```', '``'):
        return None
    if any(mark in tail for mark in '([{'):
        return None
    if '}' in tail:
        return 0.7 if tail.count('}') == 1 else 0.5
    if ']' in tail:
        return 0.35
    if ')' in tail:
        if ';' in tail:
            return -0.3
        return 0.0 if tail == ')' else 0.35
    if '>' in tail:
        return 0.1
    if tail == '.' or tail.startswith('.,'):
        return -0.25
    if ',' in tail:
        return -0.65
    if ';' in tail:
        return -1.25
    if ':' in tail:
        return -0.65 if t[q] == "'" else -0.5
    if '+' in tail or '\\' in tail:
        return -0.45
    if not tail:
        if '\n' in s:
            return -0.9 if before.endswith('.') else -1.15
        if before.endswith('.'):
            return -0.35
    return None


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, False, (1000, 1000, 1000), (False,)*3)
    _, position, previous_punctuation, ages, spaced = carry
    t = s.strip()
    value = 0.0
    if t and not any(c.isalnum() for c in t):
        q = max(t.rfind(c) for c in CLOSING_QUOTES)
        if q < 0:
            value = unquoted_ending(s, t)
        else:
            base = quoted_ending(s, t, q)
            if base is None:
                value = -0.05 if t[q] in '’”' else 0.0
            else:
                group = 0 if t[q] in "'’" else (2 if t[q] == '`' else 1)
                line = not t[q+1:] and '\n' in s
                decorative = t[q] in '’”`'
                empty = q > 0 and t[q-1] == t[q]
                value = base + (0.65 + 0.4*spaced[group]) / (1 + ages[group]/4)
                value -= 0.2*previous_punctuation + 1.65/(1 + position)
                value += 0.95*empty + 0.3*decorative + 0.35*(decorative and line)
                value += 0.2*(s.count('\n') >= 2)
    # Only the newest token is inspected. Reset all state at document boundaries.
    new_ages, new_spaced = [], []
    for age, was_spaced, signs in zip(ages, spaced, QUOTE_GROUPS):
        q = max(s.rfind(c) for c in signs)
        if q < 0:
            new_ages.append(min(1000, age + 1))
            new_spaced.append(was_spaced)
        else:
            before = s[:q]
            new_ages.append(1)
            new_spaced.append(before.endswith(' ') and
                              not before.rstrip().endswith(('(', '[', '{', ':', ',')))
    previous_punctuation = bool(t) and not t[-1].isalnum()
    return (doc, position+1, previous_punctuation,
            tuple(new_ages), tuple(new_spaced)), float(value)

