    token = prefix.token_strings[-1].lstrip()
    if not token:
        return None, 0.0

    closes = any(char in token for char in ")]}")
    has_more_marks = any(char in token for char in "([{}.,;:'\"<>]")
    if closes and (has_more_marks or "\n" in token or "\r" in token):
        return None, 0.07

    if token.startswith('"') and any(char in token for char in ",;."):
        return None, -0.10

    return None, 0.0

