    'parable': .41, 'parables': .41,
}
TIME_PHRASES = {
    'immediately after': -.48, 'immediately before': -.37,
    'shortly after': -.30, 'shortly before': -.15,
    'soon after': -.19, 'directly after': -.30,
    'just after': -.14, 'just before': -.12,
    'long after': .14, 'long before': .14, 'named after': .15,
}
TIME_UNITS = set('seconds minutes hours days weeks months years decades'.split())
VARIATION = set('vary varies varying varied differ differs anywhere'.split())
RELATIONS = set('relationship relation difference distinction connection'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    past = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    text = past + token
    value = SPEECH.get(word, -.002)
    if token.startswith(' '):
        value = WORDS.get(lower, value)
        if word == 'Upon':
            value = -.375
        elif word == 'Just':
            value = .007
    if token in {'<tool_call>', '<|im_end|>'}:
        value = .183 if token == '<tool_call>' else -.023
    if word in SPEECH:
        for ending, response in COMMENTS.items():
            if text.endswith(ending) and not past.endswith(ending):
                value = response
                break
    if word and word[-1].isascii() and word[-1].isalpha():
        match = re.search(
            r'(prefaced?|préface|foreword|adages?|parables?)$', text.lower()
        )
        if match:
            value = LITERARY.get(match[1], value)
        pair = re.search(r'(\w+)\s+(\w+)$', text.lower())
        before = pair[1] if pair else ''
        value = TIME_PHRASES.get(pair[0], value) if pair else value
        if lower == 'all':
            value = .03 if token.startswith(' ') and word == 'all' else value
            if re.search(r'after\s*all$', text.lower()):
                value = .74 if 'After' in text[-12:] else .60
            elif before == 'above':
                value = .35
        elif lower in {'after', 'before', 'post'} and before in TIME_UNITS:
            value = {'after': -.15, 'before': -.09, 'post': -.32}[lower]
        elif lower == 'between':
            if before in VARIATION:
                value = -.50
            elif before in RELATIONS:
                value = .12
        elif lower in {'age', 'aged', 'days'}:
            if before == 'old':
                value = .61 if lower == 'days' else .53
            elif lower == 'days' and before in {'early', 'these', 'those'}:
                value = .39 if before == 'early' else .22
    return (doc, text[-64:]), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:5156, a diffuse component with a few nameable hot spots.

What it does: this rank-one piece of layer 0's MLP output is almost always small
(std about 0.04), and its size depends mostly on the exact token and its local
context, with no simple concept behind the bulk of it. The model barely uses it:
switching it off changes the next-token distribution by about 5e-6 nats.

This program predicts only the strongest, nameable cases, and says 0 elsewhere:
  - the word that completes "after all" (also "above all"), about +0.6;
    "old days" and "Middle Ages" likewise;
  - "upon" in "Once upon a time", about +0.2;
  - Chinese characters that end common words of speech and feeling
    (话 話 语 語 言 感 想 记 辞 联 台 词), about +0.2;
  - the chat-template token "<tool_call>", about +0.18;
  - timing and direction adverbs ("immediately", "shortly", "later", "upon",
    "toward(s)", "often", "always" ...), about -0.12.
"""
READS = ()

# Words that complete a fixed phrase, after which the component reads strongly.
PHRASE_ENDS = {" all": ("after", "After", "above", "Above"), " days": ("old",), " Ages": ("Middle",)}
# Chinese characters that end common words for speech and feeling.
SPEECH_FEELING = set("话話语語言感想记記辞联台词")
# Timing and direction adverbs, which come out negative.
TIMING_NEG = {" immediately", " shortly", " later", " upon", " toward", " towards", " simply", " often", " always"}
# Adverbs and quantifiers that come out slightly negative.
ADVERBS = {" actually", " really", " just", " later", " further", " often", " always", " every", " everyone", " everybody", " throughout", " immediately", " towards", " toward"}


def step(carry, prefix, upstream):
    """Predicted activation at the newest token, from that token and the one before it."""
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if cur in PHRASE_ENDS and prev in PHRASE_ENDS[cur]:
        value = 0.6
    elif cur == " upon" and prev == "Once":
        value = 0.2
    elif cur in SPEECH_FEELING:
        value = 0.2
    elif cur == "<tool_call>":
        value = 0.18
    elif cur in ADVERBS:
        value = -0.1
    elif cur == " upon":
        value = -0.14
    else:
        value = 0.0
    return carry, float(value)

"""Colon detector for layers.0.mlp.down_proj:5157.

This component is a "colon" feature: it switches on at a colon token, the ':' that
introduces a label, a value, a list item or a clause. Its size depends on context:
  - a bare ':' fires at about 0.5, more strongly near the start of a document and
    less far into it;
  - a colon that closes a bracket or question/quote mark, such as '):' or '?:',
    fires more weakly (about 0.35);
  - the full-width colon '：' fires weakly (about 0.2).
Everywhere else it is near zero. The JSON-style quoted colon '":' and the '::' token
do not fire it.

The program predicts from the newest token, the document position (it counts tokens since
the document started), and how many colons earlier on the same line.
"""

import math

READS = ()

BRACKET_COLONS = {"):", "]:", "}:", "?:", "`:", ".:", "_:", "”:", "():", ")):"}
FULLWIDTH_COLON = "："

BRACKET_VALUE = 0.35
FULLWIDTH_VALUE = 0.2


def bare_colon_value(doc_position, colons_on_line):
    """Fitted by least squares on training rows: falls with document position, rises with
    earlier colons on the line."""
    return 0.76 - 0.054 * math.log(1 + doc_position) + 0.059 * min(colons_on_line, 3)


def step(carry, prefix, upstream):
    # carry: (document id, tokens since document start, colons since last newline)
    doc_id = prefix.document_ids[-1]
    if carry is None or carry[0] != doc_id:
        doc_position, colons_on_line = 0, 0
    else:
        doc_position, colons_on_line = carry[1], carry[2]
    token = prefix.token_strings[-1]
    if token == ":":
        value = bare_colon_value(doc_position, colons_on_line)
    elif token in BRACKET_COLONS:
        value = BRACKET_VALUE
    elif token == FULLWIDTH_COLON:
        value = FULLWIDTH_VALUE
    else:
        value = 0.0
    if "\n" in token:
        colons_on_line = 0
    elif token == ":":
        colons_on_line += 1
    return (doc_id, doc_position + 1, colons_on_line), value

programs.luna:
"""Approximate a punctuation detector: a bare colon is the main strong trigger."""

READS = ()
PUNCTUATION_BEFORE_COLON = frozenset(")]}.?!'\"")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    if token == ":":
        return None, 0.516

    # Closing punctuation and quotes can be joined to the colon in one token.
    if token.endswith(":") and token[:-1] and all(
        char in PUNCTUATION_BEFORE_COLON for char in token[:-1]
    ):
        return None, 0.30

    if token in {" :", "："}:
        return None, 0.12

    return None, 0.0

programs.sol:
"""Lexical approximation: negative for 'between' and repeated-letter chunks.

'Between' is the strongest word response, including several translations.
Wall/gap words and a few other separation/location words respond more weakly.
There is also an orthographic response to isolated repeated letters, especially
m and w (so mm and www fire strongly), and to the interjection Hmm.
The rules deliberately leave ordinary tokens near zero rather than memorizing
all of their small, token-specific activation differences.
"""
READS = ()

# Translations of the two-sided relation expressed by 'between'.
BETWEEN = {
    'entre': -1.25,
    'zwischen': -1.6,
    'между': -2.0,
    '之间': -0.7,
    '之间的': -0.9,
    '之間': -1.0,
    '之間的': -1.0,
    'بين': -1.5,
}


def response(token):
    word = token.strip()
    bare = word.lstrip('_-/(')
    lower = bare.lower()
    if lower == 'between':
        return -2.4 if bare.isupper() else -2.9
    if lower in BETWEEN:
        return BETWEEN[lower]
    if lower in {'wall', 'walls', 'gap', 'gaps', '墙', '牆'}:
        return -0.85
    if lower in {'against', 'behind', 'beyond'}:
        return -0.35
    if lower in {'within', 'among', 'across', 'difference'}:
        return -0.19
    if lower in {'moment', 'moments'}:
        return -0.7
    if lower == 'momentum':
        return -0.45
    if lower == 'hmm':
        return -1.15 if token[:1].isspace() else -1.35
    if lower in {'cm', 'km', 'мм', '毫米'}:
        return -1.65 if lower in {'мм', '毫米'} else -0.23

    # Only a whole repeated-letter chunk, not doubles inside ordinary words.
    if (len(bare) >= 2 and len(set(bare)) == 1
            and bare.isascii() and bare.isalpha()):
        char = lower[0]
        if char in 'mw':
            value = -2.7 if char == 'm' else -2.85
            if bare.isupper():
                value -= 0.85 if char == 'm' else 0.2
            elif token[:1].isspace():
                value += 0.35
        elif char == 'h':
            value = -2.1 if bare.isupper() else -1.5
        elif char in 'knry':
            value = -0.9
        elif char == 'i':
            value = 0.16 if bare.isupper() else 0.0
        elif char in 'elos' or (bare.islower() and char in 'bf'):
            value = 0.0
        else:
            value = -0.3
        return value * (0.8 if bare != word else 1.0)
    return 0.0


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

programs.haiku:
"""Token detector for layer-0 MLP output unit 5158 (layers.0.mlp.down_proj:5158).

The unit is almost silent everywhere except on a handful of word-like tokens,
where it goes clearly negative:
  - the English word "between" (about -2.9), the strongest and most common case;
  - the abbreviation tokens "mm" and "www" (about -2.7), also "ww" and "WWW";
  - weaker, about -1.0 to -1.4: "Hmm", the foreign words for "between"
    (zwischen, entre, между, 之间, giữa), and the doubled-letter tokens hh, nn, yy, kk, rr;
  - weaker still, about -0.9: "wall", "gap", "moment" (and plurals);
  - a little negative on "against", "behind", "within" (about -0.3), and a little
    positive on "than" (+0.15).
Every other token is predicted as 0.

The values are the typical activations per token type; the spread within a token
type is small, so a per-token lookup is enough. Case is matched exactly for the
abbreviations, so " mM" (near 0) is not confused with " mm".
"""
READS = ()

BETWEEN = {"between", "etween"}
BETWEEN_FOREIGN = {"zwischen", "entre", "между", "之间", "之间的", "之間", "giữa"}
ABBREV_STRONG = {"mm", "MM", "mmm", "www", "WWW", "Www", "ww", "WW"}
ABBREV_WEAK = {"hh", "HH", "nn", "NN", "yy", "YY", "kk", "KK", "rr", "RR"}
HMM = {"hmm"}
WALL_GAP = {"wall", "walls", "gap", "gaps", "moment", "moments"}
SPATIAL = {"against", "behind", "within"}


def step(carry, prefix, upstream):
    """Predict the unit's activation at the last token of the prefix."""
    word = prefix.token_strings[-1].strip()
    if word.lower() in BETWEEN:
        return carry, -2.9
    if word in ABBREV_STRONG:
        return carry, -2.7
    if word.lower() in HMM:
        return carry, -1.2
    if word in BETWEEN_FOREIGN:
        return carry, -1.4
    if word in ABBREV_WEAK:
        return carry, -1.0
    if word.lower() in WALL_GAP:
        return carry, -0.9
    if word in SPATIAL:
        return carry, -0.3
    if word == "than":
        return carry, 0.15
    return carry, 0.0

programs.luna:
"""Predict strong token responses to “between” and weaker relation, unit, and text cues.
The response is mostly lexical, so this sketch ignores wider context."""
READS = ()

BETWEEN_WORDS = {
    "between": -2.9,
    "entre": -1.25,
    "zwischen": -1.8,
    "между": -1.9,
    "之间": -0.8,
    "之間": -1.0,
}
RELATION_WORDS = {
    "than": 0.55, "among": -0.28, "within": -0.30,
    "behind": -0.42, "beyond": -0.37, "against": -0.39,
    "moment": -0.56, "moments": -0.80,
}

def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.casefold()

    if "between" in word:
        return None, -2.9
    if word == "etween":
        return None, -2.4
    if word in BETWEEN_WORDS:
        return None, BETWEEN_WORDS[word]
    if word.startswith("之间"):
        return None, -0.8
    if word.startswith("之間"):
        return None, -1.0

    # Distinguish mixed-case mM (a concentration unit) from mm.
    if raw == "mM":
        return None, -0.14
    if word in {"mm", "mm."}:
        return None, -2.9
    if word == "/mm":
        return None, -2.3
    if word == ":mm":
        return None, -1.25

    if word.startswith("www"):
        return None, -3.0
    if word in {"hmm", "hmmm"}:
        return None, -1.2
    if word == "mmm":
        return None, -2.4
    if word in {"wall", "walls", "gap"}:
        return None, -0.9
    if word in RELATION_WORDS:
        return None, RELATION_WORDS[word]
    return None, 0.0

programs.sol:
"""Boundary pulses and a small lexical/formatting approximation.

This weak component has heterogeneous responses rather than one reliable
semantic trigger. The program approximates its negative document-start and
thinking-boundary pulses, then a few interpretable lexical and code-format
contrasts. Ordinary unrecognized text stays close to zero. Words are matched
as whole token strings, ignoring capitalization; this is not a word parser.
"""
READS = ()

# Chat markup: (ordinary occurrence, first token of a document).
BOUNDARIES = {
    "<|im_start|>": (0.050, -0.466),
    "<|im_end|>": (-0.016, -0.231),
    "<|endoftext|>": (0.001, -0.130),
    "<think>": (-0.051, -0.540),
    "</think>": (-0.345, -0.469),
    "<tool_call>": (-0.081, -0.487),
    "</tool_call>": (0.074, -0.263),
    "<tool_response>": (0.010, -0.027),
    "</tool_response>": (-0.022, -0.514),
}

# These are named grammatical or semantic classes, not token-ID lookups.
LOCATION_WORDS = {
    "here": -0.038, "there": -0.041, "way": -0.075,
    "above": 0.055, "below": 0.034, "inside": 0.023,
    "outside": -0.031, "within": 0.017, "behind": 0.046,
}
MODALS = {
    "can": 0.001, "could": -0.036, "may": 0.016,
    "might": -0.060, "must": -0.008, "shall": -0.034,
    "should": -0.007, "will": 0.001, "would": -0.007,
    "cannot": -0.050,
}
FREQUENCY_WORDS = {
    "always": -0.036, "never": 0.044, "often": -0.050,
    "rarely": 0.038, "usually": -0.029, "sometimes": 0.025,
    "again": -0.048,
}
QUANTITY_WORDS = {
    "two": 0.033, "second": 0.040, "third": 0.044,
    "whole": -0.083, "half": -0.060, "portion": 0.063,
    "entire": -0.047, "empty": -0.064, "full": 0.029,
}
# Familiar file suffixes have distinct responses; they are not interchangeable.
FILE_SUFFIXES = {
    ".py": -0.058, ".html": -0.108, ".h": -0.073,
    ".json": -0.052, ".yaml": -0.029, ".yml": -0.023,
    ".php": -0.049, ".sh": -0.033, ".rs": -0.028,
    ".txt": 0.082, ".md": 0.031,
    ".com": -0.045, ".net": -0.042,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ""
    else:
        position, previous = carry[1] + 1, carry[2]
    word = token.strip().lower()
    value = (0.002, -0.004, 0.002)[min(position, 2)]
    if position == 0:
        value = -0.027

    if token in BOUNDARIES:
        value = BOUNDARIES[token][position == 0]
    elif previous == "<|im_start|>" and word in {"user", "assistant"}:
        if word == "user":
            value = -0.144 if position == 1 else -0.004
        else:
            value = -0.205 if position == 1 else 0.010
    else:
        lexical = None
        for words in (LOCATION_WORDS, MODALS, FREQUENCY_WORDS,
                      QUANTITY_WORDS, FILE_SUFFIXES):
            if word in words:
                lexical = words[word]
                break
        if lexical is not None:
            value += lexical
        elif word in {"please", "请"}:
            value += 0.103
        elif word == "its" and token.startswith(" "):
            value -= 0.048
        elif word == "when":
            value += 0.032
        elif word == "because":
            value += 0.040
        elif word == "same":
            value += 0.035
        elif word in {"anything", "something"}:
            value += 0.061
        elif word in {"birth", "births", "citizenship"}:
            value += 0.118
        elif "/*" in token or "*/" in token:
            value += 0.035
        elif token == "::":
            value += 0.028
        elif token == "\\t":
            value -= 0.036
        elif word.isascii() and word.isalpha() and len(word) > 5:
            if word.endswith("ity"):
                value += 0.014
            elif word.endswith("ing") and not token.startswith(" "):
                value += 0.016
    return (doc, position, token), float(value)

