"""Fires on words that say the subject is receiving, suffering, undergoing or being affected by
something: "receive", "suffer", "experience", "affected", "victim", "due", "under", and 受
("receive, suffer") in Chinese. Also fires on the preposition right after such a word
("victims of", "affected by", "suffer from"). Written as graded word tiers, with values
fitted roughly to the component's activations.

Tier 1 (about 9): 受 ("receive, suffer"), and its compounds 受到, 不受, 深受, 备受, 受け, を受け.
Tier 2 (about 2.5): other undergo-or-endure words and the passive markers 被 and 遭.
Tier 3 (about 1): English verbs and nouns of receiving, experiencing, suffering, accepting,
"affected", "victim", plus 体验, 耐, 经过, 由于.
Tier 4 (about 0.6): "under" (licensed under, rejected under) and "due" (due to); "because" 0.4.
Of "of", "by", "from", "with", "to" after a tier 1-3 word gets about 0.6.
"""
READS = ()

TIER1 = {"受", "受到", "不受", "深受", "备受", "受到了", "受不了", "受け", "を受け", "受欢迎"}
TIER2 = {
    "被", "遭", "遭到", "接受", "享受", "承受", "遇", "遇到", "经历", "感受", "感受到", "得到",
}
TIER3 = {
    "receive", "received", "receiving", "receives", "receipt", "suffer", "suffered", "suffering",
    "suffers", "experience", "experienced", "experiences", "experiencing", "undergo", "undergoing",
    "subjected", "accept", "accepted", "accepting", "acceptance", "victim", "victims", "affected",
    "receptor", "receptors", "feel", "feeling", "feels", "heard", "体验", "耐", "经过", "經過",
    "由于", "由於",
}
TIER4 = {"under": 0.6, "due": 0.6, "because": 0.4}
PREPS = {"of", "by", "from", "with", "to"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in TIER1:
        value = 9.0
    elif word in TIER2:
        value = 2.5
    elif word in TIER3:
        value = 1.0
    elif word in TIER4:
        value = TIER4[word]
    elif word in PREPS and (prev in TIER1 or prev in TIER2 or prev in TIER3):
        value = 0.6
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A spelling response to lexical 'ed' syllables, rather than grammatical -ed.

Short bed/med/hed fragments are strongest; editing, education and medicine
word starts are weaker. Common English past tenses are suppressed. Fragment
length provides a fallback for unfamiliar stems. Cyrillic ед and accented éd
get analogous responses. State keeps only the current ASCII word and last fragment,
and resets between documents.
"""
import re

READS = ()

REGULAR_VERBS = set('''absorb adsorb arm bar bob calm charm comb grab jam
probe rob rub scrub skim sob stab tab trim film form hem download comment
subtract complement exert contrast secret react report rest import accord
express hinder shift claim hover host wing partition lump correspond liken
convert cover charge obey shield dart enrich weight index warn buzz honor
pepper model settle unsettle mingle wrestle pickle hurl sprinkle toggle
baffle hassle smuggle giggle ruffle wrinkle doodle gamble paddle explore
defer center centre inter star scare martyr desire tire fire bury deny envy
levy copy apply try cry dry tie die lie marry vary tally defy ally carry rely
modify glorify'''.split())


def is_past_tense(word):
    if not word.endswith('ed'):
        return False
    stem = word[:-2]
    bases = [stem, stem + 'e']
    if stem.endswith('i'):
        bases.append(stem[:-1] + 'y')
    if len(stem) > 1 and stem[-1] == stem[-2]:
        bases.append(stem[:-1])
    return any(base in REGULAR_VERBS for base in bases)


def activation(token, word, fragment):
    s = token.lstrip(' \t\n._/-(')
    text = s.lower()
    attached = s == token
    whole = word + text if attached else text
    n = len(fragment)
    if re.fullmatch('[a-z]?ed', text):
        if is_past_tense(whole):
            return -0.1
        if text == 'bed':
            return -4.8 if whole.endswith('testbed') else -2.9
        if text == 'hed':
            return -6.0 if attached else -3.0
        if text == 'med':
            return -4.8 if attached else (-4.4 if s[0].isupper() else -3.7)
        if text == 'ed':
            if re.search('(poly|tetra|octa|dodeca|icosa)hed$', whole):
                return -5.2
            if not attached or s == 'Ed':
                return -3.9
