programs.sol:
"""Detect a single letter at a word/identifier boundary, not a word continuation.

The letter may be a word's first fragment, an initial, or a variable. Slashes
and hyphens make particularly strong cues. Case and vowels modulate the size;
English a/I, coordinate variables, contractions and escapes are weaker cues.
A lowercase-to-uppercase transition can cue camelCase; acronym continuations
and dense recent letter runs are weaker. Coarse space-plus-letter rules cover
Cyrillic, Arabic and Greek too. Strengths are fitted training averages.
"""
import unicodedata

READS = ()

# Lowercase consonant, uppercase consonant, lowercase vowel, uppercase vowel.
BOUNDARIES = {
    '-': (1.55, 0.97, 0.80, 0.50),
    '/': (1.74, 1.08, 0.88, 0.56),
    '(': (0.99, 0.83, 0.71, 0.51),
    '.': (1.06, 0.43, 0.52, 0.26),
    '_': (0.56, 0.48, 0.00, 0.17),
}


def letter_value(s, previous, previous_long):
    t = s.strip()
    if not t or not t[-1].isalpha():
        return 0.004
    c, punctuation = t[-1], t[:-1]
    if any(ch.isalnum() for ch in punctuation):
        return 0.004
    if not c.isascii():
        name = unicodedata.name(c, '')
        if s[0].isspace() and not punctuation:
            if 'CYRILLIC' in name:
                if c.lower() in 'аиуя':
                    return 0.04
                return 0.17 if c.lower() in 'во' else 0.58
            if 'ARABIC' in name:
                return 0.05 if c in 'او' else 0.55
            if 'GREEK' in name:
                return 0.10 if c.lower() in 'αεηιουω' else 0.30
        return 0.004

    vowel, upper = c.lower() in 'aeiou', c.isupper()
    if punctuation:
        if punctuation in ("'", '’', '\\'):
            return 0.03
        strengths = BOUNDARIES.get(punctuation, (0.83, 0.67, 0.58, 0.44))
        value = strengths[int(upper) + 2 * int(vowel)]
        if c in 'aI':
            value -= 0.30
    elif s[0].isspace():
        value = (0.29 if vowel else 0.50) if not upper else (
            0.35 if vowel else 0.58)
        if c == 'a':
            return 0.01
        if c == 'I':
            return -0.06
    elif not previous:
        return 0.06 if not upper else 0.10
    elif previous.isalpha():
        if previous.isupper():
            return -0.08  # Continuing an acronym.
        if previous.islower():
            if upper and previous_long:
                return 0.15 if vowel else 0.43  # A camelCase boundary cue.
            return 0.03 if upper else 0.01
        return 0.65 if vowel else 0.90  # A change from an uncased script.
    elif previous.isdigit():
        value = 0.13 if vowel else (0.23 if upper else 0.34)
    elif previous == '\\':
        return -0.04
    else:
        value = 0.49 if vowel else (0.84 if upper else 0.71)
        if c == 'a':
            value = 0.31
        if c == 'I':
            value = 0.07
    if c.lower() in 'xyz' and value > 0.2:
        value -= 0.20
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    previous_long = False if first else carry[2]
    recent_letters = () if first else carry[3]
    value = letter_value(s, previous, previous_long)
    t = s.strip()
    one_letter = bool(t and t[-1].isascii() and t[-1].isalpha()
                      and not any(ch.isalnum() for ch in t[:-1]))
    if one_letter and value > 0.2:
        # Dense runs of letter tokens are more likely spelled-out text or math
        # than a new word's initial fragment.
        density = sum(recent_letters)
        if recent_letters and recent_letters[-1]:
            value -= 0.25
        else:
            value += 0.04 - 0.04 * min(density, 6)
        if first:
            value *= 0.55 if t[:1] in '-/(' else 0.15
    recent_letters = (recent_letters + (one_letter,))[-16:]
    state = (doc, s[-1:] or previous, len(t) > 1, recent_letters)
    return state, float(value)

"""Predict a local heading-and-label signal.

Conventional headings and metadata labels have negative activation, especially
in title case at line starts. Lowercase prose and embedded identifiers are
weaker. String-opening punctuation and connectors (of, that, to, for) after
labels can have positive activation. Structured document/code boundaries have fixed
values; everything else is zero. Constants summarize training examples.
"""
READS = ()

# Strengths for recognizable families of section headings and metadata labels.
LABEL_DEFINITIONS = (
    (2.461, 'question'),
    (1.434, 'answer explanation answers'),
    (1.632,
     'introduction abstract references bibliography citation citations '
     'contributors'),
    (1.640, 'copyright disclaimer advertisement'),
    (1.658, 'posts posted logged'),
    (1.133, 'joined replies'),
    (1.120, 'download downloads'),
    (1.320, 'author authors source sources'),
    (1.624, 'description'),
    (0.996,
     'summary overview synopsis contents keywords biography background '
     'discussion'),
    (0.881, 'chapter lesson worksheet worksheets subjects courses transcript'),
    (0.917, 'example examples solution solutions'),
    (1.194, 'tags views title titles pages related'),
    (0.771, 'note notes output conclusion conclusions comment comments'),
    (0.724,
     'input definition definitions warning warnings options category '
     'categories parameters questions directions difficulty expert'),
    (0.789,
     'page home share topic topics forum subscribe ratings reply '
     'bookmark browse recommended powered'),
    (0.330,
     'date name subject instruction instructions problem problems step '
     'steps command commands homework review reviews search location '
     'edit'),
    (0.419, 'thanks hi welcome'),
    (1.157, 'published publication created updated edited filed submitted retrieved'),
    (0.820, 'isbn issn doi pdf article articles quote'),
)
LABEL_STRENGTH = {
    word: strength
    for strength, words in LABEL_DEFINITIONS
    for word in words.split()
}
# Common Chinese section, byline, and site-navigation labels.
CHINESE_LABELS = {
    word: strength
    for strength, words in (
        # Source, abstract, disclaimer, home page.
        (1.40, '来源 文章来源 摘要 免责声明 首页'),
        # Original title, publication time, editor, introduction.
        (1.00, '原标题 发布时间 责任编辑 导读'),
        # Author, title, keywords, summary, contents, download.
        (0.50, '作者 标题 关键词 简介 目录 下载'),
    )
    for word in words.split()
}

# Rows: lowercase, title case, all capitals.
# Columns: line-start heading, spaced word, attached identifier fragment.
STYLE_SCALE = (
    0.148, 0.030, 0.063,
    1.000, 0.589, 0.366,
    0.562, 0.251, 0.212,
)

def label_style(token, line):
    """Case and whether a word is a heading, spaced prose, or an identifier."""
    word = token.strip()
    capital = bool(word) and word[0].isupper()
    caps = word.isupper() and len(word) > 1
    spaced = token.startswith((' ', '\t'))
    heading = not line.strip(' \t#*-/0123456789.():[]')
    if caps:
        return 6 if heading else (7 if spaced else 8)
    if capital:
        return 3 if heading else (4 if spaced else 5)
    return 0 if heading else (1 if spaced else 2)


def opening_quote_value(token, previous, last_word):
    """Recognize opening strings rather than ordinary closing quotation marks."""
    if token in ('":"', '","', '":{"', "':'", "','", '":["', '"],"'):
        return 0.658                 # paired JSON field delimiters
    if token in (' "', " '", '"', "'"):
        if last_word.upper() == 'COMMENT':
            return 0.768                 # SQL column descriptions
        if last_word.lower() in ('title', 'label'):
            return 0.400
        if last_word.lower() == 'description':
            return 0.220
        if last_word == 'REFERENCES':
            return 0.850
        if last_word.lower() == 'name':
            return 0.420                 # named JSON/tool fields
        if last_word.lower() in ('called', 'named', 'titled',
                                 'nicknamed', 'word', 'term'):
            return 0.337
        if 'include' in previous:
            return 0.423                 # source-code include path
        if '=' in previous and '+' not in previous:
            return 0.118                 # assignment / equality string
        return -0.013
    if token in ('="', "='", ':"', ":'"):
        if last_word.lower() in ('name', 'title', 'label'):
            return 0.491
        return 0.121
    if token in ('("', "('"):
        identifier = previous.lower().replace('_', '')
        if any(part in identifier for part in ('title', 'label', 'parameter',
                                               'column', 'header', 'namespace')):
            return 0.491
        return 0.102
    if token in ('["', "['"):
        return 0.150
    return None


CONNECTOR_SCALE = {
    'of': 0.353,
    'that': 0.950,
    'to': 0.238,
    'for': 0.296,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = int(prefix.document_ids[-1])
    if carry is None or carry[0] != document:
        carry = (document, '', '', '', 0.0, 0)
    _, line, previous, last_word, prior_label, prior_style = carry
    word = token.strip()
    style = label_style(token, line)
    strength = LABEL_STRENGTH.get(word.lower(), 0.0)
    fragment_scale = 1.0
    # Join pieces when byte-pair tokenization splits a familiar label.
    if word.isalpha() and previous.strip().isalpha() and not token[:1].isspace():
        completed = LABEL_STRENGTH.get((last_word + word).lower(), 0.0)
        if completed:
            strength, style, fragment_scale = completed, prior_style, 0.80
            if style >= 6:
                style -= 3
    if word in CHINESE_LABELS:
        strength, style = CHINESE_LABELS[word], 3
    if word == '摘':                      # first character of 摘要 (abstract)
        strength = LABEL_STRENGTH['abstract']
        style, fragment_scale = 3, 0.60
    if word.lower() in ('doi', 'isbn', 'issn', 'pdf'):
        # Document/citation acronyms behave like labels regardless of case.
        style = 3 if not line.strip() else (4 if token[:1].isspace() else 5)

    label_value = -strength * STYLE_SCALE[style]
    value = label_value * fragment_scale
    quoted = opening_quote_value(token, previous, last_word)
    if quoted is not None:
        value = quoted
    if prior_label and word.lower() in CONNECTOR_SCALE:
        value = -prior_label * CONNECTOR_SCALE[word.lower()]

    # These are literal structural markers, not vocabulary-ID exceptions.
    if token == '>' and line.endswith('<issue_comment'):
        value = 0.772
    elif token == ']' and any(line.endswith('[' + level)
                              for level in ('ERROR', 'INFO', 'WARN', 'DEBUG')):
        value = 0.645

    if token == '<tool_call>':
        value = 0.131
    elif token == '<|im_start|>':
        value = -0.054
    elif token == '<|im_end|>':
        value = 0.037
    elif token == '#include':
        value = -0.212
    elif len(token) >= 40 and set(token) == {'-'}:
        value = -0.509

    line = token.rsplit('\n', 1)[-1] if '\n' in token else (line + token)[-120:]
    clean_word = word.strip('"\'`:={}(),[]')
    if clean_word.isalpha():
        if previous.strip().isalpha() and not token[:1].isspace():
            last_word = (last_word + clean_word)[-40:]
        else:
            last_word = clean_word
    return (document, line, token, last_word, label_value, style), float(value)

