}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous_doc, tail = carry if carry is not None else (doc, "")
    if doc != previous_doc:
        tail = ""

    word = token.strip().lower()
    line_prefix = tail.rsplit("\n", 1)[-1].strip()
    line_start = not line_prefix or all(
        char in "#*-=>|•·0123456789.[]() \t" for char in line_prefix
    )
    if len(line_prefix) <= 5 and line_prefix.endswith(".") and line_prefix[:-1].isupper():
        line_start = True
    if word:
        start = token.lower().find(word)
        if start >= 0 and "\n" in token[:start]:
            line_start = True

    value = 0.0
    if line_start:
        if word in STRONG_LABELS:
            value = -1.4
        elif word in MEDIUM_LABELS:
            value = -0.8

    # Forum fields can be labels even when embedded in a compact profile line.
    if word in {"posted", "tags"} and not line_start:
        value = -0.7
    elif not line_start and word in STRONG_LABELS:
        value = -0.2
    elif not line_start and word in MEDIUM_LABELS:
        value = -0.05

    # A quote after a colon or equals sign often opens a JSON or code string.
    before = tail.rstrip()
