"""A one-token pulse after a positional modifier or compound prefix.

上/中/下 (up/middle/down) produce the largest negative pulse when followed
by a single ideograph. Whole-word tokens and grammatical characters weaken
it; physical nouns and levels/time periods strengthen it. Other Chinese
location/size morphemes, English position words, and Korean 상/중/하 give
smaller pulses. Only the previous token is remembered, within a document.
This is a broad pattern: it omits fine-grained lexical/contextual variation.
"""
READS = ()
GRAMMATICAL = frozenset(
    '的了是在和与與或及也就都而于以为為者之地得这那有不无無又很将把被'
    '我你他她它们您但却卻若所其每各最多还還更必再亦仍只才便太可会會要能'
    '须須需应應当當没沒非着著过過吧吗嗎呢啊呀'
)
NUMERALS = frozenset('一二三四五六七八九十')
PHYSICAL_OR_LEVEL = frozenset(
    '人手口头頭心目山水火土木金海河田地天'
    '级級层層等阶階度旬年月季日'
)
SPATIAL_NOUNS = frozenset('''end ends side sides edge edges bound bounds boundary
boundaries layer layers ground court courts field fields case cases coast sea
water wind body back leg half part surface dimensional dimension east west
north south peninsula'''.split())
TIME_NOUNS = frozenset('year years month months day days week weeks'.split())
POSITION_WORDS = frozenset(('upper', 'lower', 'middle', 'mid'))
REFERENCE_WORDS = frozenset(('above', 'below', 'following'))
HEIGHT_WORDS = frozenset(('high', 'higher', 'low'))
DIRECTION_WORDS = frozenset(('up', 'down', 'under', 'over', 'along'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    s = raw.strip()
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    value = -0.003
    cjk = bool(s) and all('\u4e00' <= c <= '\u9fff' for c in s)
    if prev and cjk:
        last = prev[-1]
        single = len(s) == 1
        if last in '上中下':
            exact = len(prev) == 1
            if s in '上中下':
                value = 0.05
            elif s in GRAMMATICAL:
                value = -0.38
            elif s in NUMERALS:
                value = -0.90 if exact else -0.37
            elif single:
                value = -1.29 if exact else -0.80
                if s in PHYSICAL_OR_LEVEL:
                    value -= 0.60
            elif s.startswith('一'):
                value = -1.03 if exact else -0.51
            else:
                value = -0.23
        elif last in '内內外里裡高低大小前后後':
            if s in GRAMMATICAL:
                value = -0.08
            elif single:
                value = -0.35 if last in '内內外里裡' else -0.21
    elif s and s.isascii() and any(c.isalpha() for c in s):
        word, current = prev.lower(), s.lower()
        attached = not raw[0].isspace()
        if word in POSITION_WORDS:
            value = -0.44 if attached else -0.25
            if current in SPATIAL_NOUNS:
                value = -0.58
            elif word == 'middle' and current == 'of':
                value = 0.35
        elif word in REFERENCE_WORDS:
            value = -0.36 if attached else -0.15
            if current in SPATIAL_NOUNS or current in TIME_NOUNS:
                value = -0.48
        elif word in HEIGHT_WORDS:
            value = -0.15 if attached else -0.025
            if current in SPATIAL_NOUNS:
                value = -0.42
            elif attached and current in ('ly', 'est'):
                value = 0.15
        elif word in DIRECTION_WORDS:
            value = -0.16 if attached else 0.02
            if word == 'over':
                value = 0.025
        elif word in ('here', 'there'):
            value = -0.21 if attached else -0.02
