    "below", "lower", "mid", "middle", "upper", "上", "下", "中",
})
OTHER_RELATIONS = frozenset({
    "above", "bottom", "down", "following", "high", "higher",
    "内", "內", "前", "后", "後", "外", "東", "西", "高",
})
