    'ska skie ami ach anie ania enia uje ymi aj uj ze je ji cy ci ek '
    'nik aw '
).split())

def _response(raw):
    """Return baseline activation, context gain, and Polish evidence."""
    word = raw.strip()
    s = word.lower()
    start = bool(raw) and raw[0].isspace()
    lower = word.islower()
    if word in REFERENCES:
        return 3.049, 1.116, 0.3
    if s == 'polish':
        return 0.74, 0.0, 0.0
    if s in {'pl', 'pol'}:
        return 0.264, 1.809, 0.0
    if s == '.pl':
        return 2.045, 1.94, 1.0
    if s == 'się':
        return 3.77, 0.798, 1.0
    if any(c in s for c in 'ąę'):
        return 2.242, 0.622, 1.0
    if 'ł' in s:
        return 2.431, 0.722, 1.0
    if any(c in s for c in 'ńśźż'):
        return 2.25, 0.442, 1.0
    if 'ć' in s:
        return 0.76, 2.842, 0.0
    if 'ów' in s:
        return 3.058, 0.375, 1.0
    if 'ó' in s and s not in {'ól', 'ból'}:
        return 0.051, 2.072, 0.0
    if s.startswith('prz'):
        return 3.159, 0.594, 1.0
    if 'cz' in s:
        return 1.257, 2.376, 1.0
    if start and lower:
        if s in DISTINCT_WORDS:
            return 1.556, 2.047, 1.0
        if s in POLISH_WORDS:
            return -0.097, 2.925, float(s not in {'nie', 'jak', 'bo', 'tak'})
        if s in POLISH_PRONOUNS:
            return 0.42, 2.514, float(s not in {'ona', 'ono', 'wy', 'oni'})
        if s in POLISH_PREPOSITIONS:
            return -0.036, 2.333, float(s not in {'nad', 'pod'})
        if s in SHARED_PREPOSITIONS:
            return 0.027, 1.409, 0.0
        if s in ROOTS:
            return 3.675, 0.641, 1.0
        if s in PREFIXES:
            return 0.073, 2.807, 0.0
    if not start and lower:
        if s.isalpha() and s.endswith(('ski', 'ska', 'cki', 'cka')):
            return 1.199, 1.143, 0.0
        if s.isalpha() and s.endswith(STRONG_ENDINGS):
            if (s.endswith(('ych', 'enie', 'aniu', 'ują', 'owym'))
                    and not s.endswith(('nych', 'zych', 'kich', 'owych'))):
                return 0.263, 3.193, 1.0
            return 1.406, 2.474, 1.0
        if len(s) >= 3 and ('sz' in s or 'rz' in s):
            return 0.861, 2.069, 0.0
        if s in SHARED_ENDINGS:
            return 0.151, 2.901, 0.0
        if (1 < len(s) <= 4 and 'y' in s
                and s.isascii() and s.isalpha()):
            return 0.051, 2.26, 0.0
        if s in {'zn', 'zk', 'zc', 'rz', 'dz', 'dzi', 'stw'}:
            return 0.418, 2.773, 0.0
        if s in {'w', 'z', 'y'}:
            return 0.095, 2.129, 0.0
        if len(s) <= 4 and s.isascii() and s.isalpha():
            return 0.002, 1.07, 0.0
    if (any(c in s for c in 'őű')
            or s in {'ól', 'ból', 'ből', 'hogy', 'azt', 'ább'}):
        return 0.472, 0.912, 0.0
    if ('ä' in s
            or s in {'ksen', 'uden', 'isten', 'finland', 'finnish'}):
        return 0.093, 0.004, 0.0
    return 0.0, 0.316, 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    context = (0.0 if carry is None or carry[0] != doc
               else 0.985 * carry[1])
    base, gain, cue = _response(prefix.token_strings[-1])
    activation = base + gain * context
    return (doc, min(1.0, context + 0.3 * cue)), float(activation)

