programs.sol:
"""A partial lexical approximation: chat roles and familiar compound names.

Assistant headers have the largest positive response, especially after tool
results. First-document headers differ from subsequent turns. Thinking/tool
boundaries have smaller responses. Negative responses also occur on selected
programming-name continuations and MIME headers; a small dictionary covers
representative examples. Unrecognized text is zero except for weak negative
estimates on dot, underscore, and common type-name continuations.

This does not explain all the component's diverse lexical responses. The
state contains only the previous token, document position, last closing
message kind, and 80 recent characters; it resets for each document.
"""
READS = ()

BOUNDARIES = {
    '<think>': -0.42, '</think>': -0.20,
    '<tool_call>': -0.195, '</tool_call>': 0.075,
    '<tool_response>': -0.033, '</tool_response>': -0.20,
}
FIRST_BOUNDARIES = {
    '<|im_start|>': 0.218, '<|im_end|>': -0.187,
    '<tool_call>': -0.767, '</tool_call>': -0.147,
}

# Printing, numerical libraries, frameworks, and utility libraries.
MEMBER_PREFIXES = (
    (-0.45, frozenset('console fmt logger log'.split())),
    (-0.35, frozenset('np numpy pd plt tf torch pygame'.split())),
    (-0.85, frozenset('''junit springframework content view annotation awt
                        widget beans datetime keras'''.split())),
    (-0.65, frozenset('errors mock sort json reflect bytes strings'.split())),
)
# Conventional string/assertion, package/function, and macro prefixes.
UNDERSCORE_PREFIXES = (
    (-0.35, frozenset('str assert /node'.split())),
    (-1.2, frozenset('macro serde pkg pytest set _or start parse'.split())),
    (-1.8, frozenset('WRITE CLEAR GPIO FILTER'.split())),
)
TYPE_SUFFIXES = frozenset('''Parser Factory Context Provider Builder Manager
    Service Controller Handler Adapter Serializer Listener Converter
    Exception Warning Error Tree Node Token Doc Docs'''.split())

# Whole conventional names, not vocabulary IDs. Responses are rough bins.
COMPOUNDS = (
    (-0.95, ('RuleTester', 'pywraplp.Solver', '/opt/conda')),
    (-1.5, ('parserOptions', 'typescript-eslint/parser')),
    (-1.05, ('typescript-eslint', 'start_requests', 'start_urls',
             'torchaudio.pipelines')),
    (-0.55, ('eslint-plugin', 'DeprecationWarning', 'make_requests',
             'warnings.warn', 'should.have.key', 'Object.defineProperty')),
    (-1.5, ('fill_between', 'target.matches')),
    (-0.4, ('Content-Type', 'Content-Transfer-Encoding:')),
    (-0.7, ('MIME-Version',)),
    (-1.0, ('multipart/',)),
)
NAME_ENDINGS = {}
for response, names in COMPOUNDS:
    for name in names:
        NAME_ENDINGS.setdefault(name[-1], []).append((name, response))


def chat_response(token, previous, position, closed_tool):
    if previous == '<|im_start|>':
        if token == 'assistant':
            if position == 1:
                return 1.04
            return 2.137 if closed_tool == 'response' else 1.961
        if token == 'user':
            if position == 1:
                return -0.198
            return 0.505 if closed_tool == 'call' else 0.342
        if token == 'system':
            return -0.77
    if position == 0:
        if token in FIRST_BOUNDARIES:
            return FIRST_BOUNDARIES[token]
        if token == 'assistant':
            return 0.75
        if token == 'user':
            return -0.147
    if token == '<|im_start|>':
        return -0.029
    if token == '<|im_end|>':
        if previous == '</tool_response>':
            return 0.245
        return 0.005 if previous == '</tool_call>' else -0.23
    return BOUNDARIES.get(token)


def identifier_response(token, previous):
    head = previous.strip().lstrip('.')
    if token.startswith('.') and token[1:].isalpha():
        for value, names in MEMBER_PREFIXES:
            if head in names:
                return value
        return -0.04
    if token.startswith('_') and token[1:].isalpha():
        for value, names in UNDERSCORE_PREFIXES:
            if head in names:
                return value
        return -0.08
    if token in TYPE_SUFFIXES and previous and previous[-1].isalpha():
        return -0.13
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position, recent, closed_tool = '', 0, '', ''
    else:
        _, previous, position, recent, closed_tool = carry
    token = prefix.token_strings[-1]
    recent = (recent + token)[-80:]
    value = chat_response(token, previous, position, closed_tool)
    if value is None:
        value = identifier_response(token, previous)
        if token:
            for name, response in NAME_ENDINGS.get(token[-1], ()):
                if len(name) > len(token) and recent.endswith(name):
                    value = response
                    break
    if token == '<|im_end|>':
        closed_tool = ('response' if previous == '</tool_response>' else
                       'call' if previous == '</tool_call>' else '')
    return (doc, token, position + 1, recent, closed_tool), float(value)

