"""Approximate activations from formatted-chat roles and private-code names.

The component gives a strong pulse to assistant role labels and smaller responses
to user labels. Tokens beginning with an underscore get a weak negative bias.
"""

READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    current = tokens[-1]
    if len(tokens) >= 2 and current in ("assistant", "user"):
        if tokens[-2] == "<|im_start|>" and docs[-1] == docs[-2]:
            if current == "assistant":
                return None, 2.04
            if len(tokens) >= 3 and docs[-3] == docs[-1]:
                if tokens[-3] == "\n":
                    return None, 0.49
                if tokens[-3] == "<|endoftext|>":
                    return None, -0.20
    name = current.strip()
