    return None, 0.0

programs.sol:
"""A lexical signal for statistics and quantitative computation.

It is strongest on the abbreviations stat/stats, weaker on statistics,
quantification and metrics, and weak on calculation and scientific stems.
Matching
is mostly token-local, including identifier separators; whole words like state
and status are not treated as the abbreviation stat.  Similar-looking
statue/statute words also give a smaller positive response.  For split words,
common endings immediately after stat/quant receive a smaller response.
Other tokens predict zero; diffuse background and negative byte-fragment
responses are not modeled.
"""
READS = ()


def response(token, previous=""):
    word = token.strip().lstrip('._/-(\\').lower()
    capital = token.strip().lstrip('._/-(\\')[:1].isupper()
    if word == 'stat':
        if token.strip().isupper():
            return 3.1
        return 3.35 + (0.6 if capital else 0.2 if token == 'stat' else 0.0)
    if word == 'stats':
        return 4.0 + (0.55 if capital else 1.1 if token == 'stats' else 0.0)
    if word in {'statist', 'statistic', 'statistics'}:
        return 2.05 + (0.4 if capital else 0.0)
    if word == 'statistical':
        return 1.8
    if word == 'statistically':
        return 1.45
    if word == '统计':  # Chinese: statistics
        return 2.0
    if word == '統':  # The first character of Japanese 統計 (statistics)
        return 0.45
    if word == 'estad':  # Spanish/Portuguese statistics stem
        return 0.8
    if word in {'statue', 'statues', 'statute', 'statutes', 'statutory'}:
        return 1.0
    if word == 'quant':
        return 1.4 + (0.2 if capital else 0.0)
    if word in {'quantitative', 'quantify'}:
        return 0.93
    if word == 'metrics':
        return 0.7 if token.startswith(('.', '_')) else 1.25 if capital else 1.1
    if word == 'analytics':
        return 1.0 if capital else 1.4
    if word == 'calc':
        return 1.15 if capital else 1.0
    if not token[:1].isspace() and previous in {'stat', 'stats', 'statist'}:
        if word in {'istical', 'istic', 'istics', 'icians', 'ically'}:
            return 0.65
    if not token[:1].isspace() and previous == 'quant':
        if word in {'ify', 'ified', 'ifies', 'ifying', 'ifiable', 'itative'}:
            return 0.65
        if word in {'ile', 'iles', 'ity', 'ities', 'um', 'ization'}:
            return 0.15
    if word in {'analy', 'chem', 'phys'}:
        return 0.4
    if word == 'math' or word.startswith('calcul'):
        return 0.2
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ""
    token = prefix.token_strings[-1]
    value = response(token, previous)
    word = token.strip().lstrip('._/-(\\').lower()
    return (document, word), value

