programs.haiku:
"""Plural-group quantifiers and plural agreement (layers.0.mlp.down_proj:5172).

What the component does: it fires on words that mark a plural group of things, most
strongly "all" and "both" right after a plural verb or subject ("are all", "we all",
"they both"), then "these", "those", "two", "three", "many", "several" in the same
spot, and more weakly on the same words after "of" ("all of these"). It also fires on the
plural verb "are"/"were" after a plural subject ("they are", "there are", "these are"), on
"you"/"they"/"we"/"them" after "are"/"do"/"have", and on a plural noun right after one of
those quantifiers. It goes negative on a singular article or "no" right after "are" or
"were" ("there are a lot", "there are no"), which breaks plural agreement. Everywhere else
it predicts 0; the real activation is near 0 on most tokens.

The rules are word-level with one word of context, so they capture the bulk of the
signal (about 0.23 variance explained on eval) but not the diffuse small values.
"""
READS = ()

QUANT = {"all", "both", "these", "those", "two", "three", "four", "five", "many", "several",
         "each", "some", "various", "other", "among", "most", "few", "them"}
BE = {"are", "were", "'re", "’re"}
PLURAL_SUBJ = {"they", "there", "these", "those", "we", "you"}
PRONOUN = {"you", "they", "we", "them"}
AGREE_VERB = {"are", "were", "do", "have"}
SINGULAR_DET = {"a", "an", "no", "the"}
PREP = {"in", "at", "for", "by", "with", "from", "on"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if prefix.position > 0 else ""
    if word in QUANT:
        if prev in BE or prev in PLURAL_SUBJ:
            value = 2.5 if word in ("all", "both") else 1.2
        elif prev == "of":
            value = 0.9 if word in ("all", "these") else 0.4
        elif prev in PREP:
            value = 0.0
        else:
            value = 0.1
    elif word in BE:
        value = 0.45 if prev in PLURAL_SUBJ else 0.04
    elif word in SINGULAR_DET and prev in BE:
        value = -0.5 if word == "the" else -1.2
    elif word in PRONOUN and prev in AGREE_VERB:
        value = 0.7
    elif word == "of" and prev in QUANT:
        value = 0.4
    elif (prev in QUANT or prev in BE) and word.endswith("s") and len(word) > 3:
        value = 0.1
    else:
        value = 0.0
    return carry, float(value)

