programs.sol:
"""A lexical order/sequence detector with a weaker 'with' signal.

Order words, including code spellings and a few translations, respond most.
Sequence and index words respond moderately. 'With' responds weakly, except
in fixed relational phrases such as 'associated with'. The previous token
also identifies split word endings and 'order of'. State resets at document
boundaries. Unlisted tokens get zero; small miscellaneous responses are omitted.
"""
READS = ()

# Predicates and nouns which take 'with' as a complement.
WITH_COMPLEMENTS = set((
    'associated association compared compare comparison along together '
    'consistent inconsistent compatible incompatible compatibility '
    'contact comply compliance accordance deal deals dealing dealt '
    'familiar acquainted interact interacts interacting interaction '
    'interactions connection connect connected conjunction correlated '
    'correlate aligned align combined relationship relationships agreement '
    'agree agrees disagree disagreed interfere interfering conflict conflicts '
    'coincide collide affiliated related paired match confused resonate '
    'collaborated collaboration'
).split())


def spelling(token):
    return token.strip().lstrip('-._/([,<=').lower()


def lexical(token):
    word = spelling(token)
    if word == 'order':
        if token.startswith('-'):
            return 6.65
        if token.startswith(('(', '<')):
            return 3.6
        if token == ' order':
            return 5.9
        return 4.3 if token == 'order' else 5.2
    if word == 'orders':
        return 4.75 if token == ' orders' else 3.5
    if word in {'ordered', 'ordering', 'orderby', 'reorder', 'inorder',
                'preorder', 'reordered'}:
        return 3.8
    if word in {'unordered', 'orderly', 'ordereddict'}:
        return 2.6
    if word in {'sequence', 'sequences', 'sequencing', 'subsequence'}:
        return 1.5
    if word in {'sequential', 'sequentially'}:
        return 2.15
    if word.startswith('index') or word == 'indices':
        return 1.0
    # Chinese/Japanese/Korean order words and Chinese 'ordered'.
    if word in {'順', '顺', '순', '有序'}:
        return 4.0
    if word in {'序', '顺序'}:
        return 7.3
    if word == '秩序':
        return 5.0
    if word in {'排序', '排列', '程序', '序列', '订单'}:
        return 2.2
    if word == 'with':
        return 0.95 if token.strip() == 'With' else 0.64
    if word == 'avec':  # French 'with'.
        return 0.37
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    prev = spelling(previous)
    word = spelling(token)
    value = lexical(token)
    if token == ' with':
        if prev in WITH_COMPLEMENTS:
            value = 0.1
        elif previous.rstrip().endswith(','):
            value = 0.84
    elif token == ' of':
        if prev in {'order', 'orders'}:
            value = 3.0
        elif prev in {'sequence', 'sequences'}:
            value = 1.0
    elif token.lower() in {'ing', 'ings', 'ed', 'ly'} and prev == 'order':
        value = 3.0
    elif token in {'ence', 'ences', 'encing'} and prev in {'sequ', 'subsequ'}:
        value = 2.0
    elif word == 'order' and prev.endswith('rec'):
        value = 1.05  # 'recorder' contains the spelling, not the order word.
    elif token == 'order' and prev in {'pre', 'post'}:
        value = 7.0
    elif token == 'ordered' and prev == 'dis':
        value = 1.75
    return (doc, token), value

programs.haiku:
"""Layer-0 MLP component 5177 (down_proj): an "order" word detector.

The component writes a large value into the residual stream on the word "order" in
any form: " order", "-order" (as in "pre-order", "first-order"), "Order", "ORDER",
" orders", " ordered", " ordering", "OrderBy", "inorder". The bare word is strongest.
It also responds weakly to the connected words about sequence and arrangement
("sequence", "index", "sorted", "arranged", "position"), and to "with" (about 0.6).
The token right after an order word also responds when it is "of" or the "ED" of
"ORDERED" ("order of", "ORDER" + "ED"). Everything else gets 0.
The program reads only the current token and the one before it.
"""

ORDER_STEMS = ("order", "inorder")
SEQUENCE_WORDS = {"sequence", "sequences", "sequencing", "index", "indices", "indexes",
                  "indexing", "sorted", "arranged", "arrangement", "arrangements"}
WEAK_WORDS = {"position", "positions"}
READS = ()


def word_of(token):
    """A token as a lower-case word: no leading space, hyphen, dot or underscore."""
    return token.strip().lstrip("-._").lower()


def step(carry, prefix, upstream):
    word = word_of(prefix.token_strings[-1])
    previous = word_of(prefix.token_strings[-2]) if len(prefix) > 1 else ""
    if word.startswith(ORDER_STEMS):
        value = 6.0 if word == "order" else 3.8
    elif previous.startswith(ORDER_STEMS) and word in ("of", "ed"):
        value = 3.0
    elif word in SEQUENCE_WORDS:
        value = 1.2
    elif word in WEAK_WORDS:
        value = 0.4
    elif word == "with":
        value = 0.6
    else:
        value = 0.0
    return carry, float(value)

