programs.sol:
"""A detector for centered dots and related separator/multiplication marks.

High-importance examples concentrate on these small marks. Single middle
dots are strongest; a preceding Chinese or Korean token boosts Latin middle
dots. Japanese interpuncts and repeated dots are weaker. Bullets, multiplication
crosses, double colons, and single stars also respond. Star responses depend
on whether they open comments, stand alone, or adjoin other characters;
doubled stars and comment closers are suppressed. Dot-operator names are
included, as are completed byte-split Unicode math dots. Other text gets
zero. Constants approximate training averages.
"""
READS = ()

# Other centered-dot, circle, and multiplication symbols.
MARKS = {
    '･': 3.4, '‧': 2.5, '⋅': 3.7, '∙': 2.8, '⋯': 1.35,
    '●': 0.85, '○': 0.25, '◦': 0.41, '×': 0.55,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    mark = token.strip()
    spaced = token.startswith(' ')
    newline = '\n' in token
    same_doc = (prefix.position > 0 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    previous = prefix.token_strings[-2] if same_doc else ''

    # A byte-fragment token can finish a centered Unicode math symbol.
    if '�' in token and same_doc:
        completed = prefix.text_prefixes[-1][-1:]
        if completed in ('⋅', '⋯', '∙'):
            return None, {'⋅': 6.1, '⋯': 3.05, '∙': 2.8}[completed]

    if mark == '·':
        if spaced:
            value = 4.98
        else:
            if '�' in previous:
                previous = prefix.text_prefixes[-2][-1:]
            if any('\uac00' <= c <= '\ud7af' for c in previous):
                value = 7.0
            elif any('\u4e00' <= c <= '\u9fff' for c in previous):
                value = 6.1
            else:
                value = 5.05 if '\n' in previous else 5.4
    elif mark == '··':
        value = 2.2
    elif mark == '・':
        value = 3.95 if spaced else (4.15 if '\n' in previous else 4.6)
    elif mark and set(mark) == {'・'}:
        value = 0.45
    elif mark == '•':
        value = 1.18 if spaced else 1.0
    elif mark in MARKS:
        value = MARKS[mark]
        if mark == '●' and spaced:
            value = 1.07
        if newline:
            value *= 0.5
    elif mark == 'cdot':
        value = 3.67
    elif mark == 'dot':
        value = 1.3 if spaced else 0.95
    elif mark == 'bullet' and not spaced:
        value = 0.9
    elif mark == 'times' and previous.endswith('\\'):
        value = 0.23
    elif mark == 'ots' and previous.strip() in ('cd', 'ld', 'vd', 'dd'):
        value = 1.8
    elif '::' in mark:
        value = (1.13 if spaced else 0.98) if mark == '::' else 0.75
    elif '*' in mark:
        if '**' in mark or '*/' in mark:
            value = 0.0
        elif mark.startswith('/*'):
            value = 1.10 if spaced else 0.92
            if newline:
                value -= 0.35
        elif mark == '*':
            value = 0.63 if spaced else 0.48
            if spaced and previous.strip().isdigit():
                value = 0.52
            if newline:
                value -= 0.25
        elif mark.startswith('*') and mark[1:].isalpha():
            value = 0.30
        else:
            value = 0.38
    elif mark == '"."':
        value = 0.49
    else:
        value = 0.0
    return None, value

programs.haiku:
"""Middle-dot and bullet detector (layer 0 MLP, down_proj component 5178).

The component writes a strong signal into the residual stream when the current
token is a dot-like separator: the middle dot "·" (and its katakana cousin "・",
the halfwidth "･", the dot operator "⋅", the LaTeX/TeX word "cdot"), at roughly
4-6 units. Weaker responses come from the word "dot", bullet-like marks
(•, ●, ‧, one-dot leader ․), the C++/Rust "::" scope operator, "/*" comment
openers, and the asterisk / multiplication sign "*" and "×" (about 0.5). Every
other token predicts 0.

The program is stateless: it looks only at the current token's text.
"""

READS = ()

# Interpuncts and dot operators: the strongest responses.
MIDDLE_DOTS = {"·": 5.0, "・": 4.6, "･": 3.5, "⋅": 3.7, "‧": 2.4, "··": 2.6, "cdot": 3.6, "dot": 1.3}
# Bullets and dot-like marks: moderate responses.
BULLETS = {"•": 1.1, "●": 0.9, "․": 1.0, "◇": 0.6, "○": 0.3, "■": 0.3, "◆": 0.4}
# Code and markup punctuation: weak responses.
PUNCTUATION = {"::": 1.0, "/*": 0.9, "*": 0.5, "×": 0.55, "*(": 0.45}


def activation(token):
    s = token.strip()
    if s in MIDDLE_DOTS:
        return MIDDLE_DOTS[s]
    if s in BULLETS:
        return BULLETS[s]
    if s.startswith("::") or s in PUNCTUATION:
        return PUNCTUATION.get(s, 1.0)
    return 0.0


def step(carry, prefix, upstream):
    return None, float(activation(prefix.token_strings[-1]))

programs.luna:
"""Recognize conspicuous operator and separator marks in text.

The largest response is to interpuncts and centered multiplication dots;
smaller responses mark bullets, stars, crosses, and doubled colons.
"""
READS = ()


MIDDLE_DOTS = "・·･∙⋅"
BULLETS = "•‣◦"
STARS = "*∗＊"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if any(mark in token for mark in MIDDLE_DOTS):
        return None, 5.4
    if any(mark in token for mark in BULLETS):
        return None, 1.3
    if "::" in token:
        return None, 1.15
    if any(mark in token for mark in STARS):
        return None, 0.72
    if "×" in token:
        return None, 0.55
    return None, 0.0

programs.sol:
"""Lexical mean-family pulses with a small grammatical background.

Case-insensitive token spellings 'mean', 'meant', 'means', and 'meaning'
receive positive pulses, strongest for 'meant'. Subject pronouns strengthen
some pulses; passive and statistical constructions weaken them. A small
positive echo lasts one token. Intensity/focus words and possessives receive
negative corrections; temporal links, absence, and -ly endings positive ones.
This captures the rare lexical response, not most of the activation variance.
"""

READS: tuple[str, ...] = ()
PERSONAL_SUBJECTS = {'i', 'you', 'he', 'she', 'we', 'they'}
REFERENCE_SUBJECTS = {'it', 'that', 'which'}
PASSIVE_OR_NEGATED = {'is', 'are', 'was', 'were', 'be', 'been', 'being', 'not'}
STATISTICAL = {'arithmetic', 'harmonic', 'geometric', 'sample', 'population'}
INTENSITY_OR_FOCUS = {'very', 'too', 'just'}
TEMPORAL_LINKS = {'before', 'after', 'since'}
POSSESSIVES = {'my', 'your', 'his', 'our', 'their'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, echo = '', 0.0
    else:
        _, previous, echo = carry
    word = prefix.token_strings[-1].strip().lower()

    value = echo
    if word == 'meant':
        pulse = 0.32
        if previous in PERSONAL_SUBJECTS | REFERENCE_SUBJECTS:
            pulse = 0.50
        if previous == 'which':
            pulse = 0.59
        if previous in PASSIVE_OR_NEGATED:
            pulse = 0.25
        value += pulse
    elif word == 'mean':
        pulse = 0.11
        if previous in PERSONAL_SUBJECTS | {'can', 'could', 'might'}:
            pulse = 0.26
        if previous in STATISTICAL:
            pulse = 0.02
        value += pulse
    elif word == 'means':
        value += 0.18 if previous in REFERENCE_SUBJECTS else 0.075
    elif word == 'meaning':
        value += 0.08
    elif word in INTENSITY_OR_FOCUS:
        value -= 0.085
    elif word in TEMPORAL_LINKS:
        value += 0.04
    elif word == 'without':
        value += 0.07
    elif word in POSSESSIVES:
        value -= 0.036 if word == 'my' else 0.012
    elif word in {"'s", '’s'}:
        value -= 0.02
    elif word.isascii() and word.isalpha() and len(word) > 3:
        if word.endswith('ly'):
            value += 0.022

    next_echo = 0.04 if word == 'meant' else 0.0
    if word in {'mean', 'means', 'meaning'}:
        next_echo = 0.02
    return (document, word, next_echo), float(value)

programs.haiku:
"""Fires on the verb "mean" and its forms (" meant" strongest, then " mean",
" means", " meaning"), and is silent elsewhere. Values are the average activation
measured on training text."""

