"""Taxonomy and palaeontology vocabulary detector (mostly negative).

layers.0.mlp.down_proj:5180 is a sparse, word-level feature. It goes clearly negative on
words from biological classification ("tax" / "taxa" as in "parent taxon", "family",
"genus", "synonym", "endemic") and on fossil and geological-period words ("fossil",
"Jurassic", "Devon(ian)", "-aceous" endings such as "Cretaceous"). It is weakly positive on
the intensifier "very". Every other token predicts 0.
"""

READS = ()

NEGATIVE = {
    "tax": -0.45, "taxon": -0.45, "taxa": -0.3,
    "endemic": -0.55, "synonym": -0.4, "genus": -0.25, "family": -0.18,
    "fossil": -0.25, "fossils": -0.4,
    "jurassic": -0.5, "devon": -0.4, "aceous": -0.35,
}
