programs.sol:
"""A lexical make/making detector, with weaker made/makes responses.

Also recognize derivatives and selected make/do/manufacture equivalents in
other languages, plus weaker keep/render responses. Case, word boundaries,
hyphens, and a few local grammatical contexts adjust the amplitude.
Immediately following articles and selected complements carry an echo;
'file' after 'make' handles Makefile. Everything else predicts zero.
This approximates a lexical response, not general understanding of creation.
"""
READS = ()

VERB = {'make': -6.0, 'making': -5.95, 'makes': -5.4, 'made': -4.8}
DERIVED = {
    'maker': -1.8, 'makers': -1.8, 'makeup': -2.0,
    'homemade': -1.8, 'handmade': -2.0,
}
# Make/do stems and words for making, manufacture, and makers.
MAKE_EQUIVALENTS = {
    'hacer': -2.45, 'haciendo': -1.7, 'hace': -0.85,
    'faire': -0.5, 'fait': -0.4, 'fazer': -1.5,
    'machen': -1.0, 'maken': -1.45, 'làm': -1.15, 'yap': -0.8,
    'сдел': -3.3, 'сделать': -3.1, 'сделал': -1.9,
    'делать': -1.65, 'дел': -1.3,
    '作': -1.0, '做': -0.85, '制作': -1.8,
    '作出': -2.4, '做出': -2.4, '做了': -1.0,
    '造': -1.0, '制造': -1.1, '制': -0.75, '製': -1.2,
    '作り': -1.4, 'メーカー': -2.75, 'ทำ': -2.2,
}
RESULT_VERBS = {
    'keep': -0.95, 'keeping': -0.95, 'keeps': -0.8, 'kept': -0.7,
    'render': -0.9, 'renders': -0.9, 'rendered': -0.9,
    'rendering': -1.15, 'renderer': -0.5,
}
BE_FORMS = {'be', 'is', 'are', 'was', 'were', 'being', 'been'}
LEXICAL = {**VERB, **DERIVED, **MAKE_EQUIVALENTS, **RESULT_VERBS}

ECHO = {
    'a': -1.45, 'an': -1.6, 'the': -2.15,
    'this': -0.6, 'their': -0.95, 'your': -0.25, 'his': -0.4,
    'it': -0.3, 'you': -0.45, 'up': -0.7, '-up': -1.8,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position, prev_raw = '', 0, ''
    else:
        previous, position, prev_raw = carry[1], carry[2] + 1, carry[3]
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lstrip('._(/-').lower()
    value = LEXICAL.get(word, 0.0)
    # Orthographic and immediate grammatical contexts of the English verb.
    if word in VERB:
        if token.startswith('-') and word in ('made', 'making'):
            value = -2.9
        elif token[:1].isupper() and word in ('make', 'made'):
            value += 0.65
        elif not raw[:1].isspace() and token[:1].islower():
            value += 1.4 if word == 'making' else 0.8
        elif token.startswith('.'):
            value += 0.25
        if word == 'make' and previous == 'to':
            value -= 0.8 if prev_raw.strip() == 'To' else 0.15
        if word == 'make' and prev_raw.strip() in ('=', ':='):
            value += 1.0
        if word == 'made' and previous in BE_FORMS:
            value -= 0.3
        if word == 'makes' and prev_raw.strip() in ('This', 'That'):
            value -= 0.6
        if position == 0 and raw[:1].isspace() and word == 'make':
            value = -7.4
    # The component sometimes remains active on the following complement.
    if previous in VERB:
        value += ECHO.get(token.lower(), 0.0)
        if token.lower() == 'of':
            if previous == 'making':
                value -= 1.55
            elif previous == 'made':
                value -= 0.85
        if word == 'file' and previous == 'make':
            value -= 3.1
    return (doc, word, position, raw), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:5181 -- a "make" detector.

What the component does: it is a strongly negative feature on the English verb
"make" in any form (make, makes, made, making), i.e. the causative/light verb
that takes an object ("make a", "make sure", "make it").  It is about -5 to -6
on the verb itself, and about -2 on the word right after it when that word is an
object determiner ("make the", "make a", "make an") or the "file" of "Makefile".
Equivalent verbs in other languages (hacer, fazer, làm, 做, 作り, сделать) get a
weaker negative value, and "keep"/"render" a small one.  Everywhere else it is 0.

The program only looks at the current word and the word before it, so it is causal.
"""

import re

READS = ()

# Activation on the verb itself, by form (the English verb "make").
MAKE_FORMS = {"make": -6.0, "makes": -5.4, "making": -5.9, "made": -4.8}

# Words that complete a "make ___" object phrase: determiners, and "file" (Makefile).
OBJECT_AFTER_MAKE = {"the", "a", "an", "file"}

# "make/do" in other languages: a weaker version of the same feature.
MAKE_OTHER_LANGUAGES = {"hacer", "fazer", "làm", "做", "做出", "作り", "сделать", "сделал"}

# Near-synonymous causative verbs: "keep X happy", "render the pie".
CAUSATIVE_NEAR = {"keep", "keeping", "kept", "keeps", "render", "rendering"}


def word_of(token):
    """A token's word: lowercase, with spaces and punctuation removed."""
    return re.sub(r"[^\w]", "", token).lower()


def step(carry, prefix, upstream):
    word = word_of(prefix.token_strings[-1])
    previous = word_of(prefix.token_strings[-2]) if len(prefix.token_strings) > 1 else ""

    if word in MAKE_FORMS:
        return None, MAKE_FORMS[word]
    if previous in MAKE_FORMS and word in OBJECT_AFTER_MAKE:
        return None, -1.9
    if word in MAKE_OTHER_LANGUAGES:
        return None, -2.5
    if word in CAUSATIVE_NEAR:
        return None, -0.9
    return None, 0.0

programs.luna:
"""Estimate the component's response to make-verb tokens and their next article."""
