"""Predict the component's positive signal in 'of' and partitive phrases.

It predicts zero except on the exact token ' of'. That token gets a modest
signal generally, a stronger one after quantity words, and an intermediate
one after common amount, group, and kind heads in phrases such as 'part of'.
"""

READS = ()

STRONG_QUANTITY_WORDS = {
    "number", "variety", "lot", "majority", "plenty", "kinds",
    "kind", "amount",
}

PARTITIVE_HEADS = {
    "type", "types", "range", "level", "group", "part", "form",
    "member", "area", "department", "purpose", "purposes", "union",
    "aspect", "most", "thirds",
}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    if tokens[-1] != " of":
        return None, 0.0

    same_document = (
        len(tokens) > 1
        and prefix.document_ids[-2] == prefix.document_ids[-1]
