programs.sol:
"""A local spelling-transition detector, not a word-identity lookup.

Short letter fragments following vowel-ending text receive positive estimates,
especially consonant clusters, Greek letters and accented Latin consonants.
Whitespace breaks the pattern. Familiar digraphs and single vowels are weaker.
Only the preceding character is remembered; Unicode splits are repaired and
document boundaries reset it. Apostrophes after vowels and the historical
long-s letter have separate estimates. Token-specific amplitudes are not modeled.
"""
import unicodedata

READS = ()
VOWELS = frozenset('aeiouæøıαεηιουωаеёиоуыэюяъاويى')
DIGRAPHS = frozenset('ch sh th ck wh gh'.split())


def plain(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    previous = plain(carry[1]) if carry and carry[0] == doc else ''
    tail = prefix.text_prefixes[-1][-1:] if s.endswith('\ufffd') else s[-1:]
    state = (doc, tail)
    after_vowel = previous in VOWELS or previous == 'y'
    if s == 'ſ':
        return state, 0.43
    if not s.isalpha():
        value = 0.17 if after_vowel and s in ("'", '’') else 0.0
        return state, value
    if not after_vowel:
        return state, -0.007
    q, n = plain(s), len(s)
    name = unicodedata.name(s[0], '')
    vowels = sum(c in VOWELS for c in q)
    if 'GREEK' in name:
        value = (0.29 if q[0] in VOWELS else 0.59) / n
    elif 'CYRILLIC' in name:
        value = (0.05 if q[0] in VOWELS else 0.23) / n
    elif 'LATIN' not in name:
        value = 0.25 / n
    elif n == 1:
        value = -0.10 if vowels or q in 'sth' else 0.16
        if not vowels and q != s.lower():
            value = 0.43
        if q in 'ei' and q == s.lower():
            value = -0.21
    elif vowels == 0:
        value = 0.80 if q[-1] in 'rl' else 0.55
        if q in DIGRAPHS or q[0] in 'mn':
            value = 0.25
        if q[0] == 'y':
            value = 1.0
    else:
        value = max(0.0, 0.28 - 0.06 * n - 0.06 * (vowels - 1))
    return state, float(value * (0.5 if previous == 'y' else 1.0))

programs.haiku:
"""Layer-0 MLP down-projection component 5183.

Plain-terms reading: a "rare-letter fragment" detector. It responds to letters
and letter-pieces that are not ordinary English words:
  * single Greek consonant letters (ρ σ μ κ χ λ π ...), strongly;
  * single Cyrillic or accented Latin letters, weakly;
  * short Latin-alphabet pieces with no vowel (bl, ft, pl, zz, cc, ...), most
    strongly when they sit inside a word that is split across tokens (the
    "bl" of fibro|bl|asts). Ordinary words and leading-space tokens get ~0.
Greek vowels are slightly negative.

It reads only the current token and the one before it (in the same document).
"""
import unicodedata

READS = ()

GREEK_VOWELS = set("αεηιουωάέήίόύώ")
VOWELS = set("aeiouyAEIOUY")


def _script_letter(tok, script):
    return len(tok) == 1 and unicodedata.name(tok, "").startswith(script)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    inside_word = prev != "" and not prev.startswith(" ") and prev[-1:].isalpha()
    value = 0.0
    if _script_letter(tok, "GREEK"):
        value = -0.03 if tok in GREEK_VOWELS else 0.4
    elif _script_letter(tok, "CYRILLIC") or (_script_letter(tok, "LATIN") and not tok.isascii()):
        value = 0.07
    elif not tok.startswith(" ") and tok.isascii() and tok.isalpha() and len(tok) <= 3:
        if not (set(tok) & VOWELS):
            value = (0.16 if len(tok) == 2 else 0.04) if inside_word else 0.06
    return carry, float(value)

programs.luna:
"""Score word-internal alphabetic pieces, especially in other scripts.

The detector looks for an unspaced alphabetic token immediately following
another alphabetic token in the same document. Diacritics and non-Latin
letters get a stronger score; ordinary short fragments get a smaller one.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if not token.isalpha():
        return None, 0.0

    pos = prefix.position
    if pos == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    previous = prefix.token_strings[-2]
    if not previous or not previous[-1].isalpha():
        return None, 0.0

    for char in token:
        name = unicodedata.name(char, "")
        if not name.startswith("LATIN") or ord(char) > 127:
            return None, 0.013

    if len(token) <= 5:
        if token.isupper() and len(token) <= 3:
            return None, 0.008
        return None, 0.003
    return None, 0.0
